INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GCISW2UQf5G', 4, '{"title":"7","description":"<p>293、本太阳病，医反下之，因而腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000907,"note":"      本来太阳病应该解肌的，结果医反下之，攻下的药一下去，就伤到肠胃了，肠胃的功能减缓了，脾脏肿大起来，造成腹满时痛者，肚子胀满偶尔会痛，就是属于太阴，如果只要感觉肚子里面胀胀的，舌苔黄的；大便没有就是阳明证，感觉肚子里面胀满的，舌苔白的，下利，就是太阴，为什么桂枝加芍药汤，就是芍药加倍，若桂枝三，白芍就是六，张仲景在用白芍，白芍的药味是酸的，酸主收敛，所以重用白芍的时候，主收敛，脾脏一肿大的时候，芍药让脾脏收敛起来，因为脏里面静脉很多，动脉大部分是在腑里面，白芍让静脉活起来，马上收敛起来，因为加重白芍，酸主收敛，所以往往需要固表的时候，或人虚的时候重用白芍，像真武汤里面有芍药，当归四逆汤里面也有芍药，譬如芍药甘草附子汤，光靠附子把阳 壮起来的时候，怕附子太刚烈太猛烈，用芍药固起来，不要让它发阳发太过，所以芍药有固阴的功能，所以简单的讲芍药止腹痛，只要腹痛就一定加芍药，除非是大便不通的腹痛，所以小建中汤里面加重芍药，如果桂枝汤里面加饴糖没加重芍药、就只是桂枝汤加饴糖，不是小建中汤，要桂枝汤里面再加重芍药，才是小建中汤，一般制药厂做的药粉不是真正的小建中汤，大实痛者，前面是按之舒服，隐隐作痛，痛不是很强，大实痛就是不按都会痛，拒按，就是桂枝加大黄汤主之。","videoMemo":"","fangList":["桂枝加芍药汤","桂枝加大黄汤"],"bieMing":""}}', '2024-11-30T03:26:37.000Z', '2024-11-30T03:26:37.000Z', '2024-11-30T03:26:37.000Z', '293、本太阳病，医反下之，因而腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。', '2024-11-30T03:26:37.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'JIOyKhbNDhA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1k8rT4e1ahi', 4, '{"title":"8","description":"<p>294、太阴为病，脉弱，其人续自便利，设当行大黄、芍药者，宜减之，以其人胃气弱，易动故也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000908,"note":"      如果病在太阴，病人就可以看到脉很弱，跳的很缓慢，其人续自便利、大便还是继续在下利的时候，设当行大黄、芍药者，宜减之，假如这人还需要大黄、芍药的时候，要减量，因为胃气弱，易动故也，胃气本身太弱了，又需再攻实的时候，剂量要减轻，强力下攻的话，胃阳会虚掉了，所以易动故也。这时候开大黄只是协助蠕动功能而已，帮助他去实的力量，往往一般性的下利，桂枝汤重用芍药就好了。  \n\n以上讲的是太阴证。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T03:39:12.000Z', '2024-11-30T03:39:12.000Z', '2024-11-30T03:39:12.000Z', '294、太阴为病，脉弱，其人续自便利，设当行大黄、芍药者，宜减之，以其人胃气弱，易动故也。', '2024-11-30T03:39:12.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'JIOyKhbNDhA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C1EjO4E5VEr', 4, '{"title":"295、少阴之为病，脉微细，但欲寐也","description":"<p>295、少阴之为病，脉微细，但欲寐也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001001,"note":"         微脉是代表气很衰弱了，细脉代表血不够了，脉微细就是气血不足的状况，但欲寐，是少阴的主证。例：脉微细，且下焦寒到小便无法自禁，没有办法控制一直往外流，因为都没有蠕动了，膀胱口都开着，人的水是经过肾阳气化出来的，所以尿有点黄，现在他小便是白的，所以要用大剂的附子下去，现在西医连尿失禁都治不好，因为不知寒热也。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '295、少阴之为病，脉微细，但欲寐也。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('21P8xrlfp1w', 4, '{"title":"2","description":"<p>296、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故引水自救；若小便色白者，少阴病形悉具。小便白者，以下焦虚，有寒，不能制水，故令色白也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001002,"note":"       太阴证的时候是自利不渴，太阴、少阴、厥阴都会下利，只是下利的程度有深浅，如果自利不渴，就知道病在太阴，寒湿在上焦，所以他不会渴，\n      如果自利而渴者，是少阴，寒在下焦，下焦肾虚的时候，会一直在下利小便，\n      虚，故引水自救，所以会有口渴，病人会想喝水，\n      若小便色白者，少阴病形悉具，小便颜色整个变成淡白色，就是标准的少阴证，\n     为什么?因为下焦虚，有寒，不能制水，故令色白也，寒的观念就是根本没有温度了，根本不气化了，蠕动整个停摆，膀胱像一块死肉没有用，他的小便根本是漏出来的，中医有分寒热，西医就没有分寒热，西医只管发烧。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '296、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故引水自救；若小便色白者，少阴病形悉具。小便白者，以下焦虚，有寒，不能制水，故令色白也。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6S6DGv465vO', 4, '{"title":"3","description":"<p>297、病人脉阴阳俱紧，反汗出者，亡阳也；此属少阴，法当咽痛，而复吐、利。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001003,"note":"       左右手的脉又紧又浮。照理说是表寒应该无汗，结果摸到有汗，\n      就是亡阳：中医的亡阳观念，人身上的阳和阴是交接的，当阴寒很盛的时候，阳就离开了，阳就慢慢的浮出来，就是我们的体力精神慢慢的离开身体，很快走人了。这时候阳浮上来，可以摸到脉很浮，但是重按到里的时候就没有脉了，伤寒表证的浮脉，轻轻的就摸到脉，重按的时候脉跳的更强，摸到脉很浮很紧。重按就没了，这脉没有力，就知道里面完全虚掉了，病人应该没有汗，结果汗流很多，这就是亡阳，所以病人在大虚大弱的时候，脉会变的很芤很大，因为要血，又没有血，就会撑大，此际病人反而一直流汗，流汗不止，这就是脉证不合，脉证不合就很危险，所以如果看病人很虚弱，摸他的脉也很虚弱，就没有关系，来得及。如果刚好相反的，人很虚弱，脉却很大，就是亡阳了。\n     此属少阴，法当咽痛，这种状况，阳热就是讲发炎的病毒，热是很轻的，热往上走，走到喉咙，喉咙就发炎，喉咙会痛，这喉咙痛和太阳证的喉咙痛又不一样，这喉咙痛是因为身体虚掉了，里面的滤过性病毒没有地方待了，往上跑了，发炎的现象往上跑了，\n     而复吐、利，阴病一定会有下利的，为什么会吐？少阴证是从脾，从太阴传进来的，始受在太阴，本来就是津液堵在中焦，日久没有好才会进入少阴，造成上下不通利。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '297、病人脉阴阳俱紧，反汗出者，亡阳也；此属少阴，法当咽痛，而复吐、利。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7FvN42br7gv', 4, '{"title":"4","description":"<p>298、少阴病，咳而下利，谵语者，被火气劫故也，小便必难，以强责少阴汗也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001004,"note":"       少阴证的时候病在少阴，病在很里面，阴很盛，这时候如果病人呈现的咳而下利，\n      谵语者，为什么谵语？被火气劫故也，小便必难，以强责少阴汗也，这条辨最主要讲少阴病，虽然里面阴寒很盛但不可以发汗，只有在太阳表证的时候，才用汗法，少阴证的人不可能强发汗，强发汗的结果，不但没有把少阴病治好，反而会让表更虚，阳会更虚，因为发汗的药全部是阳药，一发汗阳气就散掉了，阴证的时候已经是阴比较盛，阳比较少了，还在去阳，阴会更盛阳会更少，这时候被火气劫，小便会更少，如果强发汗，津液会枯竭掉，这是很危险的动作，所以少阴病绝对不可以发汗。  \n\n     少阴证的时候小便难，下焦虚寒，肾的阳火没有办法把膀胱的水蒸化出来的时候，病人小便不通利，这时候开真武汤，这是中医的辨症论治，西医来看是摄护腺肥大时，都可以看到真武汤证。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '298、少阴病，咳而下利，谵语者，被火气劫故也，小便必难，以强责少阴汗也。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MG4UMRWukBC', 4, '{"title":"299、少阴病，脉细沉数，病为在里，不可发汗","description":"<p>299、少阴病，脉细沉数，病为在里，不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001005,"note":"这条就讲少阴病不可汗法。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '299、少阴病，脉细沉数，病为在里，不可发汗。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vdU97TdGNaV', 4, '{"title":"6","description":"<p>300、少阴病，脉微，不可发汗，亡阳故也；阳已虚，尺脉弱涩者，复不可下之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001006,"note":"      少阴病一发汗就会亡阳，阳已虚，尺脉弱涩者，阳已虚的时候，摸尺脉下焦的脉又弱又涩，涩就是血不够了，涩脉的脉形是扁扁的，复不可下之，这时候绝对不可以攻下，开处方给病人攻下的时候，一定要确定病人的血很足，怎样知道血足？摸左手的脉就知道了，开给病人发汗的药的时候，一定要摸摸他的气足不足，摸右手的脉，就是气，就知道足不足了。  \n\n解曰：少阴病，其脉微，原为阳虚，心脏无力，不可发汗，心和肾都是少阴，很微弱的状况下，再发汗会受不了，像发汗的药，像麻黄汤里面的麻黄、桂枝都是壮心的药。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '300、少阴病，脉微，不可发汗，亡阳故也；阳已虚，尺脉弱涩者，复不可下之。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TJwz5gTpmMB', 4, '{"title":"7","description":"<p>301、少阴病，脉紧，至七八日，自下利，胸暴烦，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001007,"note":"       少阴病，如果脉紧，就是里寒很盛，到七八日，自下利，如果病人有下利的现象，胸暴烦，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈，这是阴寒要去了，阴寒从下利排掉了，这种排的现象一定是自己体能恢复了，一般来说，少阴病会有自愈的现象，常见的是肠胃功能恢复了，一旦肠胃功能恢复，脾脏太阴土一旺起来的时候，土能生金，肺就跟着好，金生水，跟着心脏和肾马上就好起来了，像这种肠胃功能很好的病人，他自己会恢复，食物一下去，变成血，到心，心火一蒸，胸阳肺津就壮起来，照理说如果进入厥阴的时候，手脚就越来越冰冷了，脉紧反去者，本来是紧脉，突然就缓和下来了，就是里寒已经去 掉了，为欲解也，此条辨里面没有处方，所以为什么练功夫很好，练功夫的呼吸吐纳，就是让肠胃蠕动，在练功夫时，当吐气的时候，此气是被手指打出来的，平常要练功打肚子，可以促进肠胃的消化功能，此为后天之本。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '301、少阴病，脉紧，至七八日，自下利，胸暴烦，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dPzQmHhQPWN', 4, '{"title":"302、少阴病，下利，恶寒而蜷卧，若利自止，手足温者，可治","description":"<p>302、少阴病，下利，恶寒而蜷卧，若利自止，手足温者，可治。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001008,"note":"      反过来，如果利不止的时候，在这种条件下，观察，就死掉了，为什么手足温者，可治，中医的理论，以阴阳来看，病人独阴无阳，不治，全部是阴证，没有一点阳，没有一点动能，即死，如果手足温的，代表胃气还在，脾胃主四肢，就有救，治疗的时候用通脉四逆汤、四逆汤等，这时候要用很重的剂量。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '302、少阴病，下利，恶寒而蜷卧，若利自止，手足温者，可治。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EKRkcvcO2QS', 4, '{"title":"303、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治","description":"<p>303、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001009,"note":"        恶寒而蜷，少阴证也和麻黄汤证一样会怕冷，但是没有麻黄汤证的关节痛，他来不及痛，因为他根本没有动，倦怠在一边，如果病人开始时自烦，欲去衣被者，可治，常常会自己烦恼，把衣被踢掉，这代表阳气还在，胃气仍在，所以看到小孩没事在踢被的，没有事；少阴证到很严重的时候，呼吸出来的气，都是凉的，就危险了。 ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '303、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e5P5Y4OHc6S', 4, '{"title":"304、少阴中风，脉阳微阴浮者，为欲愈","description":"<p>304、少阴中风，脉阳微阴浮者，为欲愈。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001010,"note":"     少阴中风证，本来是应该是脉很沉且微细，如果阴脉浮起来了，代表阳气回头了，阴脉就是血脉，就是血脉回来了，代表病人自己会好。 ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '304、少阴中风，脉阳微阴浮者，为欲愈。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FlHzNQnIVN2', 4, '{"title":"305、少阴病，欲解时，从子至寅上","description":"<p>305、少阴病，欲解时，从子至寅上。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001011,"note":"       阴证要恢复的时候，都可见半夜的时候胃气回来，如果开始给病人吃治疗脏的药的时候，病人如果在午夜的时候，元气回来，半夜回元气的时候，第一个回来的就是胃气，病人感觉到饿，所有的任何药，不管轻重，不管药好不好，突然胃口大开就是病好了，所以药开对了，病人吃了一定胃口很好，表病在白天胃气回来，里病在半夜肚子饿。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '305、少阴病，欲解时，从子至寅上。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J2paoDEJgiV', 4, '{"title":"12","description":"<p>306、少阴病，吐，利，手足不逆冷，反发热者，不死；脉不至者，灸少阴七壮。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001012,"note":"       少阴病，吐，本来就会吐，吐是从太阴传过来的，手足不逆冷，反发热者，不死，代表胃气还在，中土还没有败绝，脾土还在，所以不会死，脉不至者，灸少阴七壮，就是太溪穴。 ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '306、少阴病，吐，利，手足不逆冷，反发热者，不死；脉不至者，灸少阴七壮。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JqDIUgz5xEF', 4, '{"title":"13","description":"<p>307、少阴病，八九日，一身手足尽热者，若热在膀胱，必便脓血也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001013,"note":"       一般来说，如果手脚开始热起来的时候，一直往身上热，代表胃气一直在恢复中，都是很好的现象，这是会恢复，如果热在膀胱，会小便带血，这可能是个人体质的关系，或肾里面有结石，肾结石在通过尿道的时候，会刮破很多地方，所以会有便血的现象，还是一种现象是肾脏病邪解掉的时候，会进入太阳，少阴和太阳是表里，会进入太阳的表证，如果热进入表证就流汗解掉了，这是在经脉上面就是汗解掉了；如果是在内脏上面，从肾脏传到腑上面的时候，膀胱会受热，肾脏的石头跑到膀胱里面去了，膀胱堵到发炎，都会有血的现象，如果是单纯的血结在膀胱里面，猪苓汤就来不及了，膀胱结石，用桃核承气汤把它打出来，如果只是单纯的小便有血的时候，在太溪穴的附近，肾结石穴有压痛点，可以摸到，这时候可以用猪苓汤攻。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '307、少阴病，八九日，一身手足尽热者，若热在膀胱，必便脓血也。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gT24feWT3pM', 4, '{"title":"14","description":"<p>308、少阴病，但厥，无汗，而强发之，必动其血，未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001014,"note":"         少阴病，但厥，无汗，遇到这种情形的时候，前面已经讲是少阴证了，就是告诉你脉微细，但欲寐，病人又有手脚冰冷没有汗，这时候应该温中才对，结果误用发汗走表药，会引动他的血，津液一离开了以后，血就会逆行经脉，因为水被误攻了，一发汗血就乱跑，这时候未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治，本来很好治的，就变成难治，血会流失很多，因为进入阴证的时候，他本身已经不能生血了，造血功能都衰退了，在这情况下再发汗，会动到仅剩的一些阴血，会很难治，在经方里面，遇到这种情形的时候，张仲景没有出方，大多用炙甘草汤去救逆，里虚掉了，血不足的时候，有两个方子，一炙甘草汤，一小建中汤。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '308、少阴病，但厥，无汗，而强发之，必动其血，未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dWFvyxXFVM2', 4, '{"title":"309、少阴病，恶寒，身蜷而利，手足逆冷者，不治","description":"<p>309、少阴病，恶寒，身蜷而利，手足逆冷者，不治。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001015,"note":"         身蜷而利，身疲倦下利者，手足逆冷者，代表胃的元气都没了，代表脾脏的功能完全没了，死证；这条辨就是独阴无阳，看不到阳证了，所以少阴证看到病人手脚温的，通通可以治，手脚已经都冷掉了，就完蛋了。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '309、少阴病，恶寒，身蜷而利，手足逆冷者，不治。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mmghry1DkUA', 4, '{"title":"310、少阴病，吐，利，躁烦，四逆者，死","description":"<p>310、少阴病，吐，利，躁烦，四逆者，死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001016,"note":"      不管病在那一个阶段，病人又吐又下利，给的药根本不受受，吃了炙甘草汤，拉的吐的又是炙甘草汤，脾胃的功能都没了，肠胃都没有蠕动，遇到这种情形的时候，病人会躁烦，为什么？真阳剩一点点，最后的时候，坐着死的，眼睛都闭不起来，摸他的脉又很微细，照理说烦躁应该是脉洪大，所以现在脉证不合，如果烦躁，手脚热的再加脉洪大，就是承气汤证，现在脉证相逆，就是死证。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '310、少阴病，吐，利，躁烦，四逆者，死。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4umNgRa3E8J', 4, '{"title":"311、少阴病，下利止，而头眩时时自冒者，死","description":"<p>311、少阴病，下利止，而头眩时时自冒者，死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001017,"note":"        为什么下利止，已经没有津液可以流了，完全流失掉了，而头眩时时自冒者，头晕眩的厉害，病人一定是极度的贫血，人在缺血的时候，脑就会昏，血造出来的第一个就是到头部，心脏的力量不够了，肠胃中生血的源头又没有，就会有晕眩的现象，如果这时候，看到病人，脸色有红红的，中医叫做戴阳，就是只剩一口气了，这时候用大剂的药，譬如四逆汤，开的时候用两计，不用钱来计。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '311、少阴病，下利止，而头眩时时自冒者，死。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DqhahDtXPma', 4, '{"title":"312、少阴病，四逆，恶寒而身蜷，脉不至，不烦而躁者，死","description":"<p>312、少阴病，四逆，恶寒而身蜷，脉不至，不烦而躁者，死。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001018,"note":"        少阴病，四逆，手脚都冰冷掉了，在阴证，只要手脚还有温度，就有救，因为胃气都在，所以胃阳败绝掉，就是后天都没有了，\n       不烦而躁者，烦就是情绪不好，燥就是干掉了，嘴巴都干掉了，就是伤到津液，脉又摸不到，一般来说心脏衰弱到后来没有力量，尿毒的病人，心脏病的病人，到后来都可以看到。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '312、少阴病，四逆，恶寒而身蜷，脉不至，不烦而躁者，死。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tog0x3OhuDJ', 4, '{"title":"313、少阴病，六七日，息高者，死","description":"<p>313、少阴病，六七日，息高者，死。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001019,"note":"       为什么息高？因为心脏都没有力量了，下焦都寒掉了，都没有蠕动了，气吸到喉咙就吐出去了，都没到横膈膜，代表下面功能整个都丧失掉了，临床上，癌症的病人，阴阳都分开了，就危险了，死的时候，最后的一气，会吐的很长。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '313、少阴病，六七日，息高者，死。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mNvymfvI6fy', 4, '{"title":"20","description":"<p>314、少阴病，脉微细而沉，但欲寐，汗出不烦，自欲吐，至五六日，自利，复烦躁不得卧寐者，死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001020,"note":"       这种就是失治，如果少阴病，脉微细而沉，但欲寐，汗出不烦，自欲吐，这种状况下，一剂四逆汤下去就去掉了，但是如果不及时服用，至五六日，自利，自利就是利光了，营养能源都没了，烦燥，就是已经不受药了，阳虚在上面，阳没有根了，这看起来好像阳气恢复，实际上是死证，热快绝的时候，可以看到这些现象。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '314、少阴病，脉微细而沉，但欲寐，汗出不烦，自欲吐，至五六日，自利，复烦躁不得卧寐者，死。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('INFXh23K82P', 4, '{"title":"21","description":"<p>315、少阴病，始得之，反发热，脉沉者，$f{麻黄附子细辛汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001021,"note":"       少阴病，始得之，刚开始得到少阴病的时候，\n       反发热，代表病人有表证，少阴病应该是里寒，病人的病情会进入少阴，一定是太阳、少阳、阳明还没好，进入太阴没好，才会进入少阴，所以在刚开始起证的时候，第一里寒很盛，就是下焦脉很细，张仲景会加附子，附子专门是温肾壮心阳的，所以心脏的力量不够，肾阳不足都是靠炮附子，少阴病有心和肾的问题，所以附子一下去，心脏马上壮起来，附子性烈，跑的很快，怕附子跑太快，就规定附子跑的方向，所以用细辛，细辛性上升，细辛长的就一根长长的，没有叶子，它是往上走的，附子一遇到细辛的时候，阳就往上冲，让里寒去掉，里面就热起来了，炮附也固表，像桂枝附子汤，汗发太过的时候，病人表虚掉了，桂枝汤加附子进去固表，附子会走表、如果希望附子停在中间。因为里寒很盛，要附子不要离开，细辛一下去，里面就热起来，就不会散到表面上，如果光附子下去，摸到皮肤烫的，里面还是寒的，所以选用细辛，麻黄是发汗的药，实际上，麻黄还有一个功能，就是利尿，有的人吃小青龙汤的时候，没发汗，反从尿解掉了，这是体质的关系，有的人皮毛比较扎实，小青龙汤、麻黄汤下去都没流汗，所以有时候，用麻黄不会得汗，会得小便，在这里用麻黄，小便会小出来很多，里寒很盛，这寒要去，用小便解，走小便排掉，如果是表，滤过性病毒在皮肤表面上的时候，汗一流就去掉了，这样距离最近，如果在身体里面呢？滤过性病毒在脏里面，还用发表的方法，就不行了，虽然有很多利尿剂，问题是这些利尿剂没有阳性，不是阳药，猪苓、茯苓不是阳药、三黄泻心汤，大黄去实，真正去热是靠黄连、黄芩，所以去寒要靠热药，麻黄是很热的药，用这三味热药，麻黄附子细辛汤一下去，病人小便出来，因为这时候要把滤过性病毒排出体外，唯小便最近。  \n\n       细辛遇到附子是温中，麻黄遇到附子，性就不会走表，它往下面走，如果病人是热且实，会开给病人去热及去实的药，承气汤就是这样来的，如果是少阴证的时候，是寒实，同样是有大便堵在里面，承气汤的热实是津液丧失，干掉了，寒实，是肠子没有蠕动，大便淤积在里面，就要靠附子细辛去让它蠕动，所以变成大黄附子细辛汤，大黄是去实的。  ","videoMemo":"","fangList":["麻黄附子细辛汤"],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '315、少阴病，始得之，反发热，脉沉者，$f{麻黄附子细辛汤}主之。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KL6LY2kvlo5', 4, '{"title":"22","description":"<p>316、少阴病，得之二三日，$f{麻黄附子甘草汤}微发其汗，以二三日无里证，故微发其汗也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001022,"note":"       因为有表证，所以不要麻黄走小便，就得把细辛拿掉，换成甘草，麻黄遇到甘草不是往下走，会停在中间，有一点表证但是里寒又很盛，在这状况下，不通利小便的时候，纯的少阴证，少阴脉一定微细，平常少阴证，脉微细，但欲寐，处方就是麻黄附子细辛汤，如果不是少阴证，吃麻黄附子细辛汤，第二天鼻子也干掉了。眼泪也没了，嘴巴也干掉了，因为正常的津液被小便排掉了。","videoMemo":"","fangList":["麻黄附子甘草汤"],"bieMing":""}}', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '2024-11-30T07:41:32.000Z', '316、少阴病，得之二三日，$f{麻黄附子甘草汤}微发其汗，以二三日无里证，故微发其汗也。', '2024-11-30T07:41:32.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2AYtN17VrGk', 4, '{"title":"23","description":"<p>317、少阴病，得之二三日以上，心中烦，不得卧者，$f{黄连阿胶汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001023,"note":"       得到二三日，一定津液伤到了，第二，心中烦，不得卧者，少阴证本来就是里寒，里寒很盛才会成为少阴，我们身体里面都是寒的，我们的阳热、体能、营养液下到里，这阳应该和寒相交，才会为身体所用，才会把营养的东西吸收下来，里面寒很盛的时候，就是肠胃功能蠕动太慢了，根本没有办法吸收营养，结果食物在里面坏死掉了，在肠里面会变成肠炎，少阴证再下利就危险了，所以用消炎的药，就是黄连、黄芩，黄连、黄芩，都是清热的药，杀菌力很强的，起因是肠蠕动太缓慢，鸡子黄就是鸡蛋里面的蛋黄，阿胶是驴皮熬成的膏，阿胶完全是滋阴的药，就是补阴血不足，完全补心血，少阴证的病人，脉微细，但欲寝，代表心脏已经衰落了，一定血虚了，因为肠胃蠕动太慢，没有办法正常的吸收营养，产生新的血，造血的功能不是很好，在治疗病的同时，要把血补足，因为自己来不及造血，所以开补血的药，用阿胶、鸡子黄。为什么用白芍？白芍的性是酸的，酸性的药有固摄的功能，阿胶、鸡子黄在补心脏和肾阳的血，药下去以后，因为病人的体能太差，补进去会散出来，所以用白芍把它固到。","videoMemo":"","fangList":["黄连阿胶汤"],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '317、少阴病，得之二三日以上，心中烦，不得卧者，$f{黄连阿胶汤}主之。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r77Yc98O4TY', 4, '{"title":"318、少阴病，得之一二日，口中和，其背微恶寒者，当灸之","description":"<p>318、少阴病，得之一二日，口中和，其背微恶寒者，当灸之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001024,"note":"      过去很多医家在注解灸背后的某某穴，不需要，张仲景的意思，背那儿寒就灸那儿就好了，例如膏肓寒就灸膏肓，中极寒就灸中极，灸的功能就是引阳外越，因为里阳不足了，所以灸能让脏腑肠胃的功能激发起来。  \n\n      为什么口中和，就是津液还没有伤到，如果津液伤到就燥渴了。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '318、少阴病，得之一二日，口中和，其背微恶寒者，当灸之。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GoE1mtGi8ra', 4, '{"title":"25","description":"<p>319、少阴病，身体痛，手足痛，骨节痛，脉沉者，$f{ 附子汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001025,"note":"       如果是身体寒，骨节痛，怕冷恶寒，脉弦浮紧者，就是麻黄汤，代表这寒是在表，产生全身的骨节疼痛，所以有时候得到感冒，很怕冷，摸到皮肤都会痛，就是免疫系统很好，把滤过性病毒抗在外面；附子汤的症状很像麻黄汤，但是摸到的脉是沉的，附子汤的全身痛，就是因为少阴证本来就是里寒很盛，寒就是血冷掉了，血为什么冷掉?因为水太多了，血里面有百分之七十以上是水。约百分之三十是血，如果水太多了，血太少了，水的温度是冰的，所以摸水肿的病人皮肤是冰的，就是水太盛了，水太盛造成手脚没有温度，真正供应营养到细胞的是靠血，结果里寒很盛的时候，血液循环就会受到障碍，四肢关节没有得到正常新鲜的血，造成了手足寒，骨节痛，脉沉，所以附子汤主之。  \n\n       附子汤里面有炮附，炮附本身能壮里阳，里寒很盛的时候用炮附，因为水太多了，造成少阴证，所以加茯苓，茯苓是利尿剂，实际上，全身的水能运行就是靠脾脏，因为脾是土，土能治水，所以加白朮。茯苓和白朮常常一起用，为什么用人参?人参专门健脾胃，因为水多的病人，到后来脾肾的功能就差掉了，在这虚弱的状况下得病，人参下去把脾胃的功能健起来，在经方里面，所有的胃不和，心下痞的时候，一定会用到人参，因此肠胃功能不好的时候，人参是来健肠胃的，所以有泻心汤里面一定会用到人参，最后一味药是白芍，因为静脉血液循环太慢了不动了，白芍加强它让它流回心脏，因为里面有壮心阳附子，所以再用壮心阴的白芍，方义就是如此设计的，如果加甘草，甘草一下去，结果病人肠胃的功能很好，四肢还是冷的，所以不加甘草，让药一下去马上跑到皮肤表面了。人体中动脉即阳，静脉即阴。","videoMemo":"","fangList":["附子汤"],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '319、少阴病，身体痛，手足痛，骨节痛，脉沉者，$f{ 附子汤}主之。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LQyJguV7wK4', 4, '{"title":"320、少阴病，下利便脓血者， $f{桃花汤}主之","description":"<p>320、少阴病，下利便脓血者， $f{桃花汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001026,"note":"      为什么叫桃花汤?桃花是红色的，所以桃花汤煮起来整个是鲜红的，因为里面有赤石脂，少阴证本来就是阴寒的证，如果病人下利便脓血的时候就变成危证了，本来里寒很盛，蠕动不行，这时候得到肠炎，感染滤过性病毒便脓血，会变成肠出血或肠穿孔出血，很危险的，桃花汤和黄连阿胶汤刚好相反，黄连阿胶汤是热往上冲，所以心中烦不得卧，造成病人睡不着，热就是发炎坏死的东西，如果热往下走就是桃花汤，造成病人下利带血。  \n\n     桃花汤是里寒下血的时候用的。下利分热利、寒利，最轻的一般的热利用葛芩连汤可以治好，还有黄芩汤都是热利用的，桃花汤是里寒下利，也是受到感染而来的。","videoMemo":"","fangList":["桃花汤"],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '320、少阴病，下利便脓血者， $f{桃花汤}主之。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('626TCw0842o', 4, '{"title":"27","description":"<p>321、少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者， $f{桃花汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001027,"note":"       这是发炎的太严重了，到后来肚子都痛了，外证是肚子痛了，里面肠子已经破了，小便不利，下利不止，因为膀胱里面的水都从大便走了，太阳篇介绍猪苓汤的时候，张仲景说如果利不止的时候，利小便就好了，反过来，水从大肠出来，也会小便不利，所以还是桃花汤主之。  ","videoMemo":"","fangList":["桃花汤"],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '321、少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者， $f{桃花汤}主之。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SyGNFBEJBQr', 4, '{"title":"322、少阴病，下利便脓血者，可刺","description":"<p>322、少阴病，下利便脓血者，可刺。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001028,"note":"刺关元穴，关元是止下利很好的穴道，为什么不用灸?因为里面已经肠炎了，再灸会增热，造成病毒蠕动的更快，散播的更快。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '322、少阴病，下利便脓血者，可刺。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ATafypPkx4l', 4, '{"title":"323、少阴病，吐剧","description":"<p>323、少阴病，吐剧。手足厥冷，烦燥欲死者， $f{吴茱萸汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001029,"note":"         吴茱萸汤是止吐的圣药，这就是少阴证从太阴进入少阴，少阴证没好将进入厥阴的现象，少阴证已经是很虚了，快到厥阴的时候，肝脏的血要出来，人最后的免疫系统要作最后的抵抗之前，在要出来还没出来的时侯，这时候要把肝脏的血逼出来，肝就膨胀起来，所以肝脏一肿起来顶到胃，胃受压迫就吐。手足厥冷，手脚冰冷。因为血虚掉了，因为少阴证到后来，肠胃虚掉了，没有造血的功能，所以这时候手脚一定是冰冷，烦燥欲死者，因为东西吃不下去，一直恶心想吐，情绪一定不好的，因为热在上面，本来食物因为胃的蠕动应该往下走的，胃的气就往上跑，所以吴茱萸汤主之，吐的很厉害的时候，开吴茱萸汤去止呕，吃人参、甘草、大枣，把吐过伤到的津液补回去。  ","videoMemo":"","fangList":["吴茱萸汤"],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '323、少阴病，吐剧。手足厥冷，烦燥欲死者， $f{吴茱萸汤}主之。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WmHQhlcClde', 4, '{"title":"324、少阴病，下利，咽痛，心烦者， $f{猪肤汤}主之","description":"<p>324、少阴病，下利，咽痛，心烦者， $f{猪肤汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001030,"note":"      喉咙痛有几种处理的方式，像太阳伤寒表证的喉咙痛，吃桂枝汤，感冒好了，喉咙也好了，不用吃喉咙药，阳明篇也有喉咙痛，下焦燥热，燥气往上冲，冲到脑里就是手足躁扰、发狂奔走，冲到喉咙，喉咙发炎，这时候吃喉咙药没有用，把大便清出来就好了，现在的猪肤汤是治疗少阴证的喉咙痛，后面还有甘草汤也是治疗喉咙痛的。","videoMemo":"","fangList":["猪肤汤"],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '324、少阴病，下利，咽痛，心烦者， $f{猪肤汤}主之。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TWL3eK0o7Ff', 4, '{"title":"31","description":"<p>325、少阴病，二三日咽痛者，可与$f{甘草汤};不差者，与$f{桔梗汤}。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001031,"note":"       所谓少阴病摸他的脉一定很微细，二三日咽痛者，单纯咽痛的可与甘草汤，就是单味的甘草，用甘草解毒就好了，这喉咙痛是因为阳热冲到喉咙来，如果是在胸腔的话是黄连阿胶汤，\n      不差者，吃了甘草汤没好的，一定是有痰在里面，痰在最高的地方会加桔梗，前面的甘草加桔梗就好了。  ","videoMemo":"","fangList":["甘草汤，桔梗汤"],"bieMing":""}}', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '2024-11-30T08:47:02.000Z', '325、少阴病，二三日咽痛者，可与$f{甘草汤};不差者，与$f{桔梗汤}。', '2024-11-30T08:47:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p8oR4siOeWr', 4, '{"title":"32","description":"<p>326、少阴病，咽中伤，生疮，不能语言，声不出者，$f{苦酒汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001032,"note":"喉咙痛的现象再进一步，严重到生疮，不能语言，声不出者，这时候桔梗甘草汤已经来不及了，要用苦酒汤，苦酒就是醋，为什么叫苦酒?酒变成酸的就是醋，酒不好喝就是苦酒","videoMemo":"","fangList":["苦酒汤"],"bieMing":""}}', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '326、少阴病，咽中伤，生疮，不能语言，声不出者，$f{苦酒汤}主之。', '2024-11-30T09:16:29.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7lCxh5s5Vnb', 4, '{"title":"327、少阴病，咽中痛，$f{半夏散及汤}主之","description":"<p>327、少阴病，咽中痛，$f{半夏散及汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001033,"note":"","videoMemo":"","fangList":["半夏散及汤"],"bieMing":""}}', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '327、少阴病，咽中痛，$f{半夏散及汤}主之。', '2024-11-30T09:16:29.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C38Bgs7hhnH', 4, '{"title":"328、少阴病，下利，$f{白通汤}主之","description":"<p>328、少阴病，下利，$f{白通汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001034,"note":"","videoMemo":"","fangList":["白通汤"],"bieMing":""}}', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '328、少阴病，下利，$f{白通汤}主之。', '2024-11-30T09:16:29.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xKmFCyXWGfP', 4, '{"title":"329、少阴病，下利，脉微者，与$f{白通汤}","description":"<p>329、少阴病，下利，脉微者，与$f{白通汤}。利不止，厥逆无脉，干呕烦者，$f{白通加猪胆汁汤}主之。服汤，脉暴出者死，微续者生。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001035,"note":"       这时候已经很危险了，所以白通加猪胆汁汤主之，很多伤寒、疟疾、霍乱后期就是这样子，拉到没有东西拉了，肠胃整个停滞，这时候为什么病人会有干呕烦者?只剩一点点的生命力了，病人完全虚掉了，虚掉的时候会有烦躁的现象。\n\n     白通加猪胆汁汤就是白通汤加猪胆汁，过去的看法，这已经是很危险的时候了，阴阳相隔了，不管原因是什么病，照理说脉微弱下利病人应该虚掉了，结果病人烦躁，这是逆证，脉证不合，有的人只剩一口气了，摸他脉一息十至，这人快死了，很多癌症的病人就是这样，这时候白通汤下去，必然没有感觉，为什么加猪胆汁和人尿?因为这两个不但有滋补的功能，最重要的是这二个是非阴寒的药，他能把阴阳相隔的东西打开来，把白通汤引到阴去，尿用童子尿，若无胆亦可用，所以人尿比胆汁重要，用胆汁是为了帮助消化。  \n\n      脉暴出者死，微续者生，什么叫暴出?喝了汤药以后，如果脉突然跳的很强，这是药力发出来的脉，不是真正元气回来的脉，脉微微出来，代表病人收到了，有的人不受药就完了，受药的时候，脉会微微的跳起来。  \n\n学者到此再学会用白头翁汤，桃花汤。伤寒、疟疾、霍乱没有不会治的。","videoMemo":"","fangList":["白通汤","白通加猪胆汁汤"],"bieMing":""}}', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '2024-11-30T09:16:29.000Z', '329、少阴病，下利，脉微者，与$f{白通汤}。利不止，厥逆无脉，干呕烦者，$f{白通加猪胆汁汤}主之。服汤，脉暴出者死，微续者生。', '2024-11-30T09:16:29.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rkp1WLonifd', 4, '{"title":"36","description":"<p>330、少阴病二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气，其人或咳，或小便利，或下利，或呕者，$f{真武汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001036,"note":"      或，是副证，不一定看得到的现象，主证是腹痛，小便不利，四肢沉重疼痛，少阴病本来就是里寒很盛，水湿很盛，如果小便很正常出来的话，小便一定是白的，四肢很痛就是附子汤，现在小便不利了，已经是水堵在里面了，属于虚寒的积水，为什么腹痛，水通通堵在下焦，下焦肠子里面的水分太多，肠壁上的血液循环一定不好，所以肚子会痛，这时候用真武汤主之。  \n\n      茯苓三钱，芍药三钱，生姜二片，白朮二钱，用白芍止腹痛，腹痛的原因是因为肠壁上的静脉血管的血，没有办法回流心脏，身上五脏六腑的血通通要回到肝，再从肝的静脉出来，这时候开白芍，白芍能让血很快地归肝。  ","videoMemo":"","fangList":["真武汤"],"bieMing":""}}', '2024-11-30T09:23:27.000Z', '2024-11-30T09:23:27.000Z', '2024-11-30T09:23:27.000Z', '330、少阴病二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气，其人或咳，或小便利，或下利，或呕者，$f{真武汤}主之。', '2024-11-30T09:23:27.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m62CD1ygwnD', 4, '{"title":"37","description":"<p>331、少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止，脉不出者，$f{通脉四逆汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001037,"note":"      要内外通达就是用通脉四逆汤，下利清谷，吃进去的食物通通跑掉了，这时候里寒外热，就是肠胃通通没有蠕动了，吃进去的食物直接流出来的，不是大出来的，阳虚的时候，肛门的口都收不了直接流出来的。  \n\n      通脉四逆汤里重用炙甘草，再加生附，配合干姜在用，像通脉四逆汤、白通汤、桃花汤大部分都是用在伤寒、霍乱、瘟疫的时候，但有的时候是五苓散，要临症上辨症论治。  ","videoMemo":"","fangList":["通脉四逆汤"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '331、少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止，脉不出者，$f{通脉四逆汤}主之。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AkK38PXbNn3', 4, '{"title":"38","description":"<p>332、少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，$f{四逆散}主之。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001038,"note":"      四逆散里面有炙甘草、枳实、柴胡、芍药，实际上四逆散是大柴胡的变方，大柴胡汤里面把大黄和黄芩拿掉，就变成四逆散，为什么有四逆散?因为是少阴证，少阴证寒里较多，发炎的现象比较少，四逆散和四逆汤不一样，四逆散很轻的，四逆汤很重的，四逆散实际上在临床上看的时候是胆结石，胆结石的病人手脚冰的，痛的冒冷汗，四肢厥逆，因为是胆结石堵到的，不是肠炎，不是有病毒，所以不用黄芩，也不是大便堵到所以不用大黄，用柴胡，柴胡入少阳，入半表半里中间，用白芍止腹痛，枳实专门去在十二指肠、胃下方、消化系统刚开始的地方堵到的时候用的，炙甘草让药停在上焦。  \n\n      四逆散用散剂，四味药等量捣成粉，用米汤来服，如果确定病人是胆结石，四逆散里面再加滑石、五倍子、海金沙，因为加了滑石大便出来会很快，会有下利，所以治疗胆结石的时候，四逆散要饭后吃，饭后吃是为了让食物顶在下面，药粉在上面，让药尽量入胆，不要走太快，用炙甘草就是不希望药走太快，再饭后吃就是让药停的更久，不然会药走了，石头还没有完全排出来。胆结石的来由，可能是三餐不定时，或者吃得太油腻，结果胆汁没有正常分泌，胆汁的分泌是来自心脏搏动的压力，我们治疗的时候。用炙甘草来强心、用柴胡通利三焦、用黄芩去除湿热，用枳实打开胆管，这个处方就已经是治疗胆结石的基本处方；我们可以再加上神农本草经上面的滑石、五倍子、海金沙等，处方就开好了。  \n\n胆结石的主证： \n      一：在阳陵泉下一寸的胆结石穴有压痛点。 \n\n      二：痛起来的时候，胸痛彻到背后去，从胆的地方痛到肩膀上去。 \n\n       三：腹诊的时候，胆经的日月会有压痛点。 \n","videoMemo":"","fangList":["四逆散"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '332、少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，$f{四逆散}主之。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('map0SrcIUwc', 4, '{"title":"39","description":"<p>333、少阴病，下利六七日，小便不利，咳而呕，渴，心烦不得眠者，$f{猪苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001039,"note":"        猪苓汤是用在水和热并结，猪苓汤在太阳篇里面讲到病人上焦口渴烦躁、小便不利；小便不利就是热堵到了，热就是发炎了，内症可能是膀胱炎或肾结石堵到了，少阴证也有猪苓汤，其原因不一样，症是一样的，也是一样水热并结，下利六七日，小便不利，咳而呕，渴，心烦不得眠者，也是热，但是少阴证是虚热，太阳证是移热，同样是水堵到了，所以用猪苓汤主之。 \n\n 利水的方子：  \n\n        一：五苓散，如果是表热造成的小便不利，表太热了水气不得下降就是五苓散。 \n        二：如果是表寒，寒束在表上面，水没有办法发散，水结在下焦就是小青龙汤。 \n        三：如果是里面虚寒掉的造成小便不利的就是真武汤。 \n        四：猪苓汤是水热并结，里面发炎了，西医用试纸测小便里有红血球，因为结石把输尿管刮破了，造成小便带血，所以猪苓汤里面有阿胶止血。  \n","videoMemo":"","fangList":["猪苓汤"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '333、少阴病，下利六七日，小便不利，咳而呕，渴，心烦不得眠者，$f{猪苓汤}主之。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s2JI5qoIp0p', 4, '{"title":"40","description":"<p>334、少阴病，得之二三日，口燥咽干者，急下之，宜$f{大承气汤}。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001040,"note":"       少阴病里面本来就已经是阴寒很盛了，如果转成口燥咽干，就是病人已经从阴转成阳了，从少阴证转成阳明证的现象，这是好的现象，这时候赶快把它去掉，刚从阴回到阳的时候，元气还没有很恢复，结果大便燥结在肠里面，还是用大承气汤攻，所以不管病从那来，只要症一样，少阴篇里面还是有用到大承气汤的；如果病人没有口燥咽干，里面津液很多，舌苔白的，大便不通，就是大黄附子细辛汤证，这是寒实的时候用。口燥咽干就是热实，口不燥咽不干就是寒实。  \n\n       这些都是张仲景预防的设施，从阴证转成阳证的时候，照理说是有治，结果进入阳明证的时候，津液还会再耗损，本来阴证已经很虚热了，进入阳明证大承气汤不攻掉，津液一直没有办法恢复，反而会很危险。 ","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '334、少阴病，得之二三日，口燥咽干者，急下之，宜$f{大承气汤}。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('goQZdrQp9Oi', 4, '{"title":"41","description":"<p>335、少阴病，自利清水，色纯青，心下必痛，口干燥者，急下之，宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001041,"note":"      本身是少阴证，所以肠胃蠕动就不是很好，大便堵在里面，结果大便干掉了变成硬块，这时候胆汁一直流出来胆汁是帮助消化的，胆汁并没有办法攻坚，把大便打散要靠芒硝，胆汁是青色的，胆汁通过大肠出来，所以自利清水，色纯青，青水就是胆汁，心下必痛，胃里面难过，胃痛，口干燥者，急下之，至此已可确定是肠中有燥屎，立下大承气汤，不可犹豫。  ","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '335、少阴病，自利清水，色纯青，心下必痛，口干燥者，急下之，宜$f{大承气汤}。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gN5OivbPMVg', 4, '{"title":"42","description":"<p>336、少阴病，六七日腹胀不大便者，急下之，宜$f{大承气汤}。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001042,"note":"      大承气汤和大黄附子细辛汤是表里药，要会区别会用，一个是热实，一个是寒实用的。  ","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '336、少阴病，六七日腹胀不大便者，急下之，宜$f{大承气汤}。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l8a3NaiVgOl', 4, '{"title":"337、少阴病，脉沉者，急温之，宜$f{四逆汤}","description":"<p>337、少阴病，脉沉者，急温之，宜$f{四逆汤}。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001043,"note":"      血脉通通冷掉了，手脚冰冷掉了，赶快用四逆汤。","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '337、少阴病，脉沉者，急温之，宜$f{四逆汤}。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gmfrcymncZ5', 4, '{"title":"44","description":"<p>338、少阴病，饮食入口则吐，心中温温，欲吐复不能吐，始得之，手足寒，脉弦迟者，此胸中饮实，不可下也，当吐之；若膈上有寒、干呕者，不可吐也，急温之，宜$f{四逆汤}。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001044,"note":"       这条辨讲的是寒实，寒代表不动了，实代表有东西堵到了，有东西梗到的时候，饮食入口则吐，吃东西下去就吐出来了，心中温温，就是胃里面很难过，欲吐复不能吐，吃东西吃不下去，想吐又吐不出来，始得之，刚开始得到的时候，手足寒，脉弦迟者，手脚冰冷，弦脉就是有水，脉迟代表没有蠕动代表寒，是寒实结在上焦，此胸中饮实，实是隔在胸口上焦，不可下也，当吐之，不要用攻下的，采吐法，没有药，用肥皂水也可以，针灸也可以，扎内关，心里想吐，就吐出来了，内关是心包经的，管心意的；若膈上有寒、干呕者，干呕就是恶心，但是里面空的，根本没有东西，连水都没有，空就是虚的，这时候不可吐也，急温之，宜四逆汤，根本没有东西，所以不可以用吐的，用温法，用四逆汤来温它。 ","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '338、少阴病，饮食入口则吐，心中温温，欲吐复不能吐，始得之，手足寒，脉弦迟者，此胸中饮实，不可下也，当吐之；若膈上有寒、干呕者，不可吐也，急温之，宜$f{四逆汤}。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aDkFYio5rAJ', 4, '{"title":"45","description":"<p>339、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001045,"note":"       如果少阴病，下利，脉微涩，呕而汗出，代表肠胃的阳虚掉了，胃的津液一直在丧失，一直在下利，\n       数更衣，就是一天到晚跑厕所，\n       反少者，津液丧失很多，肚子里面根本没有东西拉了，\n       当温其上，灸之，可以用温灸的方法，下利很严重的时候，灸神阙，会用到灸一定是寒利，寒就是拉出来的很多，可是没有味道，灸神阙的时候隔盐灸。  \n\n以上讲的是少阴证。  \n\n       例：有一西医是小儿科医生，下利清谷，又全身肌肉、关节酸痛，半年了，下利清谷代表肠胃太寒了，没有热度没有胃阳，所以没有办法消化，寒到后来全身关节会痛就是虚寒，附子汤，刚开始用生姜泻心汤，如果用泻心汤，这种症状，甘草泻心汤比生姜泻心汤好，因为生姜泻心汤比较着重在湿热的部分，甘草泻心汤比较着重在虚寒的部分，病人早上吃了生姜泻心汤，下午说半年来第一次感觉食物停在胃里面，到晚上十点又发病了，所以要用附子汤，附子汤里面重用干姜，加炙甘草，这是少阴证的下利。如果是实寒就是大黄附子细辛汤证。  \n","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '2024-12-02T03:52:14.000Z', '339、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。', '2024-12-02T03:52:14.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'P7xmAJf0vZ9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RvbNIUzv6EB', 4, '{"title":"1","description":"<p>340、厥阴之为病，消渴，气上撞心，心中疼热，饥而不欲食，食则吐蚘，下之，利不止。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001101,"note":"       太阴影响到中焦，少阴影响到下焦，到了厥阴的时候，中焦、上焦都冷掉了，肠胃里面都冷掉了以后，里面没有消化的能力，没有抵抗力在里面的时候，人吃的东西里面的寄生虫就开始躲在身体里面，因为肠胃常年不好，没有办法把它消化掉排出去，虫卵就在身体里面生成虫，遇到这种情形的时候，寒热并结，通通列入厥阴证，所以到了有虫的阶段就会看到厥阴证。  \n\n        中医小儿科中望诊上，唇上有白点，很整齐的排列，眼睛下方稍微黑黑的，脾开窍在唇，有白点代表中寒，上面有黑黑的代表上热，寒热并结了，有虫的时候腿上的虫区（百虫窝）会有压痛点，病人的症状消渴，就是上焦有热，热在上焦所以口渴，气上撞心，热气往上冲，因为热气被下面的寒顶上来的，心中疼热，感觉胃里面辣辣的很烫，好像吃到大蒜一样，饥而不欲食，肚子感觉到饿，却吃不下东西，代表脾脏的功能还在，但是胃里面不好了，虫在里面所以吃不下去，食则吐蚘，因为东西吃下去，虫也在吃，下之，利不止，本来就是肠胃比较寒了，如果攻下，就下利不止了，就更危险了。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '340、厥阴之为病，消渴，气上撞心，心中疼热，饥而不欲食，食则吐蚘，下之，利不止。', '2024-12-02T04:02:39.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FeCTKX7k0q3', 4, '{"title":"341、厥阴中风，脉微浮，为欲愈；不浮，为未愈也","description":"<p>341、厥阴中风，脉微浮，为欲愈；不浮，为未愈也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001102,"note":"      如果病人厥阴证的时候中风，脉微浮，微浮代表免疫系统恢复了，代表阳气回来了，所以这时候肝血很足，身体很好的人，如果不幸病进入厥阴的时候，他会痊愈的，因为肝脏是最强的。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '341、厥阴中风，脉微浮，为欲愈；不浮，为未愈也。', '2024-12-02T04:02:39.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fu2QhjkVPvz', 4, '{"title":"342、厥阴病，欲解时，从丑至卯上","description":"<p>342、厥阴病，欲解时，从丑至卯上。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001103,"note":"       所以阴证要恢复的时候都是在半夜。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '342、厥阴病，欲解时，从丑至卯上。', '2024-12-02T04:02:39.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6PxQNlZHy4b', 4, '{"title":"343、厥阴病，渴欲饮水者，少少与之，愈","description":"<p>343、厥阴病，渴欲饮水者，少少与之，愈。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001104,"note":"     厥阴病的时候，如果想喝水，渴欲饮水，代表内脏功能慢慢恢复中，因为免疫系统强起来了，把病毒赶出去了，自然而然就会好起来，不需要用药的。  \n","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '343、厥阴病，渴欲饮水者，少少与之，愈。', '2024-12-02T04:02:39.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V5mPgx4EDDo', 4, '{"title":"344、诸四逆厥者，不可下之，虚家亦然","description":"<p>344、诸四逆厥者，不可下之，虚家亦然。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001105,"note":"这是废话，这条辨可能是从别的地方来的，前面已介绍过许多了。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '344、诸四逆厥者，不可下之，虚家亦然。', '2024-12-02T04:02:39.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('46pIMwC1b8j', 4, '{"title":"345、伤寒，先厥，后发热而利者，必自止，见厥复利","description":"<p>345、伤寒，先厥，后发热而利者，必自止，见厥复利。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001106,"note":"       一般来说，伤寒就是表寒，可是厥阴证的时候，因为病毒已经进入到身体里面，看不到表证的，看不到发热恶寒，所以感冒有症状的，代表免疫系统很好，伤寒，先厥，厥阴证的病人得到感冒没有症状的，一得到感冒，马上就昏迷过去了，后发热而利者。病人又发热回来，发热代表免疫系统强起来了，把病毒排出去，排出去会下利，下利的时候代表病毒跟着大便清出来，肠胃功能恢复的时候利会自止，如果又昏迷过去的时候，代表抵抗力又输了，又会下利。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '345、伤寒，先厥，后发热而利者，必自止，见厥复利。', '2024-12-02T04:02:39.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zLroluFvykA', 4, '{"title":"7","description":"<p>346、伤寒，始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中。食以素饼，微发热者，知胃气尚在，必愈；恐暴热来出而复去 也。后三日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，为厥相应，故期至旦日夜半愈。又三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001107,"note":"       看到厥阴证的时候，如果昏迷、精神不好、手脚冰冷的时间，和发热的时间差不多，譬如厥五天热五天，或者是热比较多冷比较少，代表免疫能力还很强，自己慢慢会好，如果昏厥或逆冷的现象比较多，\n       始发热六日，厥反九日而利，就是病很深了，抵抗力不够了，如果手脚冰冷是四逆，如果冰冷到手肘就是厥了，阴寒到极限了，厥就是阴之尽，就很危险了，这种症状当不能食，\n      今反能食者，恐为除中，除中讲的就是回光返照，当胃气完全停顿的时候，冲阳脉都没有了，摸他手脚冰冷的，病人开始吃点东西，就是老天爷不希望病人作饿死鬼；\n     食以素饼，微发热者，知胃气尚在，必愈，吃了东西以后，开始微发热，热慢慢起来的，知道胃气尚在，还有机会好；\n     恐暴热来出而复去也，这热就是食物所产生的热能，\n     后三日脉之，其热续在者，期之旦日夜半愈，过三天再摸脉，如果热还在，就会晚上的时候恢复回来，胃气会正常，这就可以救，\n     为什么?所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，为厥相应，厥相应就是热和冷厥的时间相同的，这病人不会死，故期至旦日夜半愈。又三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也，为什么会痈脓？热就是免疫系统赢了，因为病在厥阴，热气发出来的时候，会把病毒赶出去以后，病毒不会马上离开身体，病毒进入某处，譬如进入肠子里面就会化脓的现象，就是邪热太过了。  \n","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '2024-12-02T04:02:39.000Z', '346、伤寒，始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中。食以素饼，微发热者，知胃气尚在，必愈；恐暴热来出而复去 也。后三日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，为厥相应，故期至旦日夜半愈。又三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。', '2024-12-02T04:02:39.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nefs7Sbpuzh', 4, '{"title":"347、伤寒","description":"<p>347、伤寒：脉迟，六七日，而反与$f{黄芩汤}彻其热。脉迟为寒，今与黄芩汤，腹中应冷，当不能食，今反能食，此为除中，必死。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001108,"note":"       伤寒的表证都有，恶寒怕冷，全身骨节酸痛都有，可是摸病人的脉迟，脉证不合，\n       而反与黄芩汤彻其热，靠黄芩汤来去他的热，\n       脉迟为寒，今与黄芩汤，复其热，黄芩汤是去热下利的药，结果腹中应冷，当不能食，今反能食，此为除中，这是说看到的是真寒假热，以为发热恶寒是有热，结果开寒凉的药下去，一攻，里面的寒更寒，造成除中，就是胃气完全没有了，这时候用大剂四逆汤来救逆，不可见死不救。  ","videoMemo":"","fangList":["黄芩汤"],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '347、伤寒：脉迟，六七日，而反与$f{黄芩汤}彻其热。脉迟为寒，今与黄芩汤，腹中应冷，当不能食，今反能食，此为除中，必死。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2wZ33lIMQHA', 4, '{"title":"348、349、伤寒","description":"<p>348、349、伤寒：先厥后发热，下利必自止。而反汗出，咽中痛者，其喉为痹，发热，无汗，利必自止。若不止，便脓血。便脓血，其喉不痹。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001109,"note":"      伤寒，如果是先厥后发热，手脚冰冷到手肘的地方，突然发热，代表胃的元气还在，下利必自止。\n     如果下利没有止，而反汗出，厥阴证的时候津液已经伤到了，因为免疫系统就是在津液里面，津液伤到的状况之下，病人在流汗，就变成是表虚掉了，这是很危险的状况，临床上看病人，病人已经很虚弱了，可是病人又一直在流汗，就代表病人的皮肤不能固表，人的元气、元阳、精神，高蛋白的东西一直往外流失，体力通通流失掉\n     如果咽中痛者，其喉为痹，病毒移转跑到喉咙上，喉咙就会发痛，\n     如果发热，无汗，利必不自止，热散不掉，热会往下走，利必自止。\n     若不止，便脓血，这肝炎的东西出来，到喉咙上，就喉咙痛，如果没有到喉咙往下走的时候，下利就会便脓血。\n     其喉不痹，便脓血的话，喉咙就不会痛，所以发炎的滤过性病毒，中药也杀不掉它，免疫系统也杀不掉它，它一定要有出路，出去的时候从大便或往上跑，想尽办法把滤过性病毒赶出去。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '348、349、伤寒：先厥后发热，下利必自止。而反汗出，咽中痛者，其喉为痹，发热，无汗，利必自止。若不止，便脓血。便脓血，其喉不痹。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('giivldpky62', 4, '{"title":"10","description":"<p>350、伤寒，一二日，至四五日，前厥者，必发热；前热后厥者，必厥深热亦深，厥微者热亦微。厥应下之，而反发汗者，必口伤烂赤。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001110,"note":"      这条辨对应前面的条辨，张仲景的意思是如果进入厥阴证，得到中风伤寒表证的时候，因为里面已经虚掉了，肠胃津液已经不够了，肠胃津液不够的状况下，切记不要发汗，汗的来源是肠胃的津液，误汗的时候，造成口伤烂赤，会把肝里面的黏液发到嘴巴上来了，感冒发烧的时候用汗解，如果是厥阴证的时候就不可以汗解，厥阴证的时候滤过性病毒在肝里面，发皮肤的汗，跟肝没有关系，反而让肠胃的津液更伤，免疫系统受到伤害。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '350、伤寒，一二日，至四五日，前厥者，必发热；前热后厥者，必厥深热亦深，厥微者热亦微。厥应下之，而反发汗者，必口伤烂赤。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NZ4SgcAofw2', 4, '{"title":"351、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈","description":"<p>351、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈。厥终不过五日，以热五日，故知自愈。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001111,"note":"     昏迷了五天，又热五天，到第六天的时候应该发冷的，结果病人不冷了，就是病会好了，代表胃气恢复了，就不会冷了。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '351、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈。厥终不过五日，以热五日，故知自愈。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TE4E0kxMJ5A', 4, '{"title":"352、凡厥者，阴阳气不相顺接，便为厥","description":"<p>352、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001112,"note":"      厥就是手脚冰冷到手肘、膝盖，阴阳气不相顺接，就是血液循环产生障碍，血液循环通的时候，人就发热了，不通的时候，心脏衰弱的时候人就昏迷了。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '352、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bX934YlJdF8', 4, '{"title":"13","description":"<p>353、354、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为藏厥，非若蛔厥也。蛔厥者，其人常自吐蛔。今病者静，而复时烦，此为蛔厥。蛔上入膈，故烦。须臾复止，得食而呕又烦者，蛔闻食臭出，其人当吐蛔也，蛔厥者，$f{乌梅丸}主之，又主久利。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001113,"note":"       病人有烦躁的现象，脉微弱，少阴，厥阴都有，少阴证的是烦躁不得卧是持续的，厥阴证的烦躁，有时候躁有时候不躁，这是脏厥和蛔厥的不一样，\n      蛔厥者，其人常自吐蛔，虫就从嘴巴吐出来，现在病者静，而复时烦，有的时候静，有的时候烦躁，此为蛔厥，所以肚子里面有虫，病人就会有这种现象，\n      蛔上入膈，故烦，虫往上冲的时候造成烦的现象，得食而呕，吃东西进去又呕吐出来，因为蛔闻食臭出，其人当吐蛔也。\n      蛔厥者，乌梅丸主之，又主久利，乌梅丸除了打虫以外又可以用在久利上，实际上病人会产生蛔厥的，就是胃里面太寒了，胃里面太冷的时候容易生虫，为什么列入厥阴证里面?他的胃冷，就是因为肝脏，肝是解毒的脏，人身上的毒，肝都会排掉，可是如果肝脏寒的话，在中医讲肝寒的时候，就是肝的解毒功能并不是很强，进入厥阴证的时候，很多病毒都跑到肝里面去了，肝脏的解毒功能又不很正常，这时候造成虫很容易在胃里生长，虫的体温是跟着人的体温的，人吃东西的时候虫也跟着吃东西。胃寒的时候又不吃东西，虫在里面就饥寒交迫，虫肚子饿的时候，虫往上跑，一上来病人的情绪就会很烦躁，在病人的嘴唇上可以看到白白的点，还有病人会肚子痛，一般来说肚子痛就是里寒，里寒的时候用小建中汤重用芍药，芍药是桂枝的两倍，里寒的话脉应该是沉紧，如果肚子痛摸到脉是浮大就是肚子里面有虫，为什么脉会很大?因为虫在动，一吃东西虫也跟着抢就会吐出来，这就是蚘厥。  \n\n     虫的性，虫闻到酸则静，本来虫都在动，一吃到酸的就静下来了，\n     得辛则服，虫吃到很辛辣的东西就乖了，\n     得苦则泄。吃到苦的就往下走，苦就是中药消炎的药，\n乌梅丸就是从这三个角度来设计去虫。  ","videoMemo":"","fangList":["乌梅丸"],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '353、354、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为藏厥，非若蛔厥也。蛔厥者，其人常自吐蛔。今病者静，而复时烦，此为蛔厥。蛔上入膈，故烦。须臾复止，得食而呕又烦者，蛔闻食臭出，其人当吐蛔也，蛔厥者，$f{乌梅丸}主之，又主久利。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l8jMyvhMvXV', 4, '{"title":"14","description":"<p>355、伤寒，热少，厥微，指头寒，默默不欲食，烦躁，数日小便利色白者，此热除也；欲得食，其病为愈；若厥多而呕，胸胁烦满者，其后必便血。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001114,"note":"       在进入肝脏的时候，就是进入人的最近一道的抵抗系统，在检查病人的时候，发现病人的热慢慢的回头，病人在虚寒的时候，摸病人是冰冷，且病人的脉很弱很细，代表脉证相符，这就没有危险，如果病人一点元气都没有，摸到病人的脉很大很壮，就不好了，这就是《内经》里面的真脏脉，就是元阳快没有了，如果脉证合，病人热慢慢回头，体力慢慢恢复、\n     热少，厥微，刚开始热很少，手脚一点点冰冷，指头寒，默默不欲食，烦躁，这种人就是人元气要恢复的时候，就是这种现象，肝病的人，小便看的很清楚，厥阴也是热，得到急性肝炎的，一得到肝病小便就变成茶的很热，\n    数日小便利色白者，此热除也，发炎的现象没有了；欲得食，胃口开了，这几种现象代表厥阴证要痊愈了，只要看到病人体能慢慢的回头，胃口慢慢的打开，都是好的，突然吃东西都是不好的，\n    如果，若厥多而呕。手脚一天到晚都冰冷，恶心又吃不下东西，\n    胸胁烦满者，其后必便血，这是热太过了，里面发炎的现象很厉害，为什么呕?因为厥阴是肝脏，一热起来的时候，肝肿起来就顶到胃，此即木克土，实际上胃并没有问题，热太多的时候，就会胸胁烦满，热没有地方渲泻，就往肠子里面跑，大便就会带血。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '355、伤寒，热少，厥微，指头寒，默默不欲食，烦躁，数日小便利色白者，此热除也；欲得食，其病为愈；若厥多而呕，胸胁烦满者，其后必便血。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a3lg9gkJudT', 4, '{"title":"15","description":"<p>356、病者手足厥冷，言我不结胸，小腹满，按之痛者，此冷结在膀胱关元也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001115,"note":"       膀胱结到的时候，小腹痛是主证，就是中极到关元这一带剧痛，\n膀胱结有四种状况： \n      一：水结膀胱，少腹痛，最明显的状况是小便不利，这时候用五苓散。 \n      二：血结膀胱，少腹痛，小便不利，用桃核承气汤。 \n      三：热结膀胱，少腹痛，小便红涩，小便出来有刺刺的感觉，用猪苓汤。 \n      四：冷结膀胱，也是少腹痛，小便色白，用真武汤。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '356、病者手足厥冷，言我不结胸，小腹满，按之痛者，此冷结在膀胱关元也。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KZJXaEcx38C', 4, '{"title":"16","description":"<p>357、伤寒发热四日，厥反三日，复热四日，厥少热多，其病当愈。四日至七日，热不除者，其后必便脓血。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001116,"note":"       厥阴病的时候，病人发热的时间比手脚冰冷的时间多，代表病人的体能很好，其病当愈，一般来说自己会痊愈，如果没有痊愈，代表热没渲泻的地方，小便没有清出来，厥阴证是肝里面的滤过性病毒，如果没办法完全清出来，就会在身体里面，病毒如果在表就发汗发掉了，如果在厥阴就由小便跑出来了，如果从小便出不去了，病毒就往大肠跑，大便就会带脓血。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '357、伤寒发热四日，厥反三日，复热四日，厥少热多，其病当愈。四日至七日，热不除者，其后必便脓血。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fVkimnhPnOg', 4, '{"title":"358、伤寒厥四日，热反三日，复厥五日","description":"<p>358、伤寒厥四日，热反三日，复厥五日。其病为进；寒多热少，阳气退，故为进也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001117,"note":"     如果冷的时间比较多，热的时间比较少，复厥五日，冷的时间越来越延长，这病为进，病越来越重；寒多热少，阳气退，故为进也，病在加深。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '358、伤寒厥四日，热反三日，复厥五日。其病为进；寒多热少，阳气退，故为进也。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xY8LtDLXEX0', 4, '{"title":"18","description":"<p>359、伤寒六七日，脉微，手足厥冷，烦燥，灸厥阴，厥不还者，死。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001118,"note":"      伤寒六七候以后，从太阳、少阳、太阴、少阴，进入厥阴了，这时候脉微，手足厥冷，摸到脉很微细，手脚冰冷，烦燥，灸厥阴，厥不还者，死，看到病人手脚冰冷，照理说病人里面阴寒很盛了，肠胃功能都不好了，身体都虚弱了，结果病人烦躁，这烦躁就是人处于心脏正要衰弱的时候，病人会有这种情绪很烦躁的现象，这就是阳气要脱的现象，如果烦躁了以后，起脉，脉微微的回来了，胃口开起来了，手脚热起来了，这手脚一热起来代表胃气回头了，就是这人有救了。胃气如果不回头了，手脚还是冰冷的，一般来说这种比较难治，很危险。癌症的末期都可以看到，尤其是肝癌。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '359、伤寒六七日，脉微，手足厥冷，烦燥，灸厥阴，厥不还者，死。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('91quNYGQprA', 4, '{"title":"360、伤寒发热，下利，厥逆，躁不得卧者，死","description":"<p>360、伤寒发热，下利，厥逆，躁不得卧者，死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001119,"note":"       照理说伤寒就是发热，如果发热的现象兼有下利，厥逆，躁不得卧者，这种就是死，在厥阴证里面，最担心的就是烦躁不得卧，人到最后关卡的时候，到肝脏里面的时候，如果肝的功能没有办法把癌细胞排出体外的时候，元阳要离开的时候，都会看到这种烦躁的现象，下利就是体能一直排出来，厥阴篇讲的都是下利，平常看到这情形，除了大肠癌外，病人都是大小便不禁了，要赶快把利止掉，不止掉就很危险了。有时候看他利止了，结果是里面没有东西利了，遇到这种情况的时候，一般用大剂的四逆汤，下利的话用赤石脂禹余粮汤，用涩剂去止利。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '2024-12-02T07:00:10.000Z', '360、伤寒发热，下利，厥逆，躁不得卧者，死。', '2024-12-02T07:00:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V0Vpz5KqKvH', 4, '{"title":"361、伤寒，发热，下利至甚，厥不止者，死","description":"<p>361、伤寒，发热，下利至甚，厥不止者，死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001120,"note":"       照理说下利是越利越寒，体能都没有了，手脚冰冷了，如果病人发热，代表肠胃功能回来了，利应该会自止，现在发热，下利至甚。厥不止者，这时候下利不止反发热，手脚一直冰冷，没有办法热起来的这都是死证。除了癌证的末期、肝病的末期。还有霍乱痢疾的上吐下泻，好的津液都吐光了，下泻又把肠胃的津液泻掉了，就会有这种现象。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '361、伤寒，发热，下利至甚，厥不止者，死。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dL2RKSbD0d8', 4, '{"title":"21","description":"<p>362、伤寒，六七日下利，又发热，其人汗出不止者，死，有阴无阳故也。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001121,"note":"       如果人在很虚弱的状况之下，胃气恢复的时候，病人下利兼有症状是发热，不是烦躁，发热就是手脚摸到热，摸到热还在利这就不会死，没关系，如果病人汗出不止，汗血同源，汗的来源就是阳的津液，如果下利，表汗又一直在流，整个肠胃都干掉了，这种就是死证，有阴无阳，就是阳脱了，阳脱掉就会有这种现象。用白通汤加猪胆汁和人尿，白通汤可以通阳，大剂的用，靠人尿硬把阴阳相隔打开。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '362、伤寒，六七日下利，又发热，其人汗出不止者，死，有阴无阳故也。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zJW4AgFT617', 4, '{"title":"22","description":"<p>363、伤寒，五六日，不结胸，腹濡，脉虚，复厥者，不可下，此为亡血，下之死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001122,"note":"一般来说，有伤寒表证下利的话，会结胸，不结胸就是病往里面走了，腹濡，病人的肚子摸起来软软的，脉虚，复厥者，不可下，此为亡血，下之死。所以虚证不可下，虚证的人绝对不可以攻下，为什么?因为有腹濡，如果心下鞕满是实痛要攻下，如果肚子难过，要先检查清楚，有东西在里面才可以攻，没有东西在里面不可以乱攻，如果脉虚，手脚冰冷又很虚弱，病人是里虚的状况，本来还没死，一攻死的更快。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '363、伤寒，五六日，不结胸，腹濡，脉虚，复厥者，不可下，此为亡血，下之死。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2ftjWPN2zaW', 4, '{"title":"364、发热而厥，七日，下利者，为难治","description":"<p>364、发热而厥，七日，下利者，为难治。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001123,"note":"        照理说发热手脚冰冷都是里阳不足了，里面的肠胃功能没有了，肠胃没有蠕动，这时候手脚都是冰的，这种发热的现象都是人体最后一道系统，遇到这种情形的时候，人已经极虚了，若再碰到下利。代表阳气都没有了，大肠和肺相表里，肺就是胸阳，一直下利就是肺气不够了。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '364、发热而厥，七日，下利者，为难治。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G0pAGlRoI13', 4, '{"title":"365、伤寒，脉促，手足厥逆者，可灸之","description":"<p>365、伤寒，脉促，手足厥逆者，可灸之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001124,"note":"       灸中脘关元，如果是一般的伤寒表证，脉浮紧，不会用灸。用麻黄汤去发表，现在脉促，手足厥逆者，脉跳的数，手脚又冰冷，这都是进入厥阴证了，所以厥阴证的寒证，代表肝脏的功能衰弱下去了，就会看到这现象，还有下利，厥阴和少阴一样，主的是吐、利。 ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '365、伤寒，脉促，手足厥逆者，可灸之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0y8tF2iBeGi', 4, '{"title":"366、伤寒脉滑而厥者，里有热也，$f{白虎汤}主之","description":"<p>366、伤寒脉滑而厥者，里有热也，$f{白虎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001125,"note":"       只要对证，不管病在太阳、少阳、阳明，都会有白虎汤证。只要确定里面是热，是经热，就是血脉神经的热，一旦病人血里面的水不足的时候，就会用到白虎汤，如果厥阴证的病人，伤寒，吐、利太多了，病人的水不够了，也是属于白虎汤。  ","videoMemo":"","fangList":["白虎汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '366、伤寒脉滑而厥者，里有热也，$f{白虎汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GAw9uUvyEt7', 4, '{"title":"367、手足厥寒，脉细欲绝者，$f{当归四逆汤}主之","description":"<p>367、手足厥寒，脉细欲绝者，$f{当归四逆汤}主之。若其人内有久寒者，宜$f{当归四逆加吴茱萸生姜汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001126,"note":"       当归四逆汤是中医治疗冻疮的主方，处方还是桂枝汤的加减，手足厥寒，脉细欲绝者，实际上心脏极度的衰竭了，所以加护病房里面，靠维生机的病人都是当归四逆汤证，摸他的手脚都是冰冷的，心脏的血没有办法运行到四肢的末梢，四肢就缺氧，会坏死掉，这就是造成冻疮，除了冻疮外，紧急的时候也在用的，桂枝和白芍等量，由于动脉和静脉两个相等长，血液就会加速，平常胖子开三钱，人都昏迷了，靠维生机的时候用三两都不过分，因为身体里面完全没有功能，完全要靠药力，桂枝和白芍一定等量，如果桂枝少白芍重，会造成血管爆裂，因为出去的力量不够，人已经极虚了，肠胃的功能不够了津液也不够了，怕里面的东西梗到，所以用通草，通草是很轻的润肠剂，连麻子仁对病人来说都太强了，可是不攻又不行，因为怕里面有脏的东西，所以用通草，同时再加炙甘草、大枣，把津液都补回来，平常张仲景很少用补药，因为病人需要，病人在失血的状况下，所以用当归，把血补足，细辛壮里阳，让下焦的阳往上升，下面的阳往上走，整个人能循环起来，为什么不用生姜?生姜是散胃里面的水，病人有恶心呕吐的时候才会用生姜，现在要把水补回来，所以不用生姜。  \n     \n      若其人内有久寒者，宜当归四逆加吴茱萸生姜汤主之。\n             这内有久寒，讲的是胃寒，在厥阴篇里面讲的，实际上是肝太寒了，引起的胃的功能不正常，所以用当归四逆加吴茱萸生姜汤主之、吴茱萸是最好止呕的圣剂，寒就是有水，所以加生姜把水排掉。  ","videoMemo":"","fangList":["当归四逆汤","当归四逆加吴茱萸生姜汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '367、手足厥寒，脉细欲绝者，$f{当归四逆汤}主之。若其人内有久寒者，宜$f{当归四逆加吴茱萸生姜汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xPgrd6hLe7a', 4, '{"title":"27","description":"<p>368、大汗出，热不去，四肢痛而拘急，又下利，厥逆而恶寒者，$f{四逆汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001127,"note":"       如果有发热，应该汗出就都解掉了，现在大汗出，\n      热不去，就是津液伤到了，四肢痛而拘急，关节会痛，就是津液不足了，血液循环就不好，四肢关节就会痛，\n     又下利，厥逆而恶寒者，已经血液循环不好了，\n     又下利，代表里寒很强，这时候又手脚冰冷，这里的恶寒和太阳的恶寒不一样，麻黄汤的恶寒是怕冷，这里的恶寒是虚掉的冷，四逆汤主之，四逆汤都是救逆的，里寒很盛的时候用，所谓里寒就是里面的功能都没有了，四逆汤里面用干姜和生附，很危险的时候，可以炮附生附并用，生附可以壮心阳，炮附使关节打通，同时有壮肾阳之功。  ","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '368、大汗出，热不去，四肢痛而拘急，又下利，厥逆而恶寒者，$f{四逆汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qL2WweaRmG8', 4, '{"title":"369、大汗，若大下利而厥冷者，$f{四逆汤}主之","description":"<p>369、大汗，若大下利而厥冷者，$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001128,"note":"        汗和津液就是中医讲的阳，所以大汗出的时候就是亡阳了，阳就是人的体能营养液，若大下利而厥冷者，下利很多，食物没有了，就是血的源头都没有了，就是亡阴了，阳没了阴也没了，就是四逆汤主之，所以在伤寒表证的时候，汗出不止是桂枝汤加附子，用炮附收表阳。  ","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '369、大汗，若大下利而厥冷者，$f{四逆汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Js3qFcBpvEj', 4, '{"title":"29","description":"<p>370、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜用$f{瓜蒂散}。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001129,"note":"       什么叫乍紧?有的时候紧，有的时候不紧，病人手足厥冷，病人手脚冰冷的时候，摸到脉应该是微细的，代表虚掉了，结果脉变的乍变，一下子紧，一下子不紧，代表邪结在胸中，这时候心下满而烦，饥不能食者，病在胸中，当须吐之，这是寒实，要确定有东西才会采吐法，如果是虚的，病人没有东西，病人会虚烦，虚烦的脉就不会紧，紧代表有东西堵到了，宜用瓜蒂散，这是从脉证来知道胸中有实。","videoMemo":"","fangList":["瓜蒂散"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '370、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜用$f{瓜蒂散}。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VCFzNmEp2pD', 4, '{"title":"30","description":"<p>371、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔，水渍入胃，必作利也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001130,"note":"      伤寒本来就是肠胃的功能缓掉了，手脚冰冷就是进入厥阴证，还有心下悸胃已经没有吸收的功能了，胃不能吸收水分，这时候水跑到胃里面，水停在中间就会有动悸，就是水饮很多，所以像肌肉跳动、眼皮跳，就是有水饮，都是真武汤证就是水逆行离开血了，遇到这种情形的时候，要先治水，中焦的水最好的药就是茯苓，下焦的水用猪苓，上焦的水就用半夏，胸腔里面用十枣汤，现在水在胃里面所以用茯苓甘草汤，加甘草让药停在胃里面，真正的主药是茯苓，所以茯苓二，甘草一，吃了茯苓甘草汤，水排掉了后，再治手脚冰冷，来不及治的话，水跑到胃里面，这胃要把它当成肠，就会变成下利。小肠是火，水火不容，水这下去就水火未济，大便出来全部都是水。  ","videoMemo":"","fangList":["茯苓甘草汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '371、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔，水渍入胃，必作利也。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s24uOe5EJQF', 4, '{"title":"31","description":"<p>382、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{麻黄升麻汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001131,"note":"      麻黄升麻汤专门治疗上热下寒，所以麻黄升麻汤是寒热并用的汤剂，而且是补泻寒热并用在一个方子里面，为什么张仲景设计这方子?就是担心病人进入厥阴的时候，被医生误下了，误下了之后，如何去救他?伤寒六七日，大下后，如果是太阳伤寒表证的时候，被攻下会变成结胸或心下痞，不会有寸脉沉而迟的现象，这是直接进入厥阴了，寸脉讲的是阳脉，所以阳脉很弱了，里面的阳气很弱了，手足厥逆，手脚冰冷，这时候下部脉不至，尺部的脉没有了，这时候咽喉不利，唾脓血，肝是藏血的脏，人的血进入肝以后，肝过滤血后，血再从肝的静脉出来到身上来，肝脏有血管直接到子宫、大肠、到下焦里来，下焦一寒掉后，下焦凝固了，血没有办法下来，血就往上冲逆了，一冲到喉咙，喉咙就肿起来，这是血逆行经脉，严重的话就会吐血，所以肝病到后来会吐血，就是肝血逆往上走，全身只有一条血管没 有倒勾，就是肝脏到大肠的血管，就是没有瓣膜，所以肝病就是利用这管道把病毒排出去，泄利不止，就是肠胃都冷掉了，麻黄升麻汤主之。  \n\n        有当看到病人，嘴巴吐血，肝血往上，舌苔有热，又下利清谷，脉又很弱，又寒又热，这时候用麻黄升麻汤，这方子是经方里面用药最多的。如果是胃癌的病人半夜吐血的症状，则是用黄土汤加减来治疗。升麻，顾名思义，升麻是向上的，升麻性向上，有升提的作用，所以如果病人有坠症，譬如脱肛、疝气，腹膜如果破了，小肠坠出来了，一般是开刀，但是开刀只有治标，这儿好了可能那儿又破了，这是因为腹膜没有力量了，张仲景在金匮里面立蜘蛛散，用住家屋檐下的蜘蛛，把蜘蛛在铁皮锅烤干，磨成粉，作散剂吞服，慢慢腹膜就长出来了，可是腹膜长出来之前，要先把肠子收回去，一节肠子漏在外面，到时候堵到了烂掉了，张仲景说少腹疼痛入腹。就是讲疝气，针灸的时候，左边腹痛扎右脚，右边腹痛扎左脚，肝经的大敦穴下针，一痛就收回去了，然后下肝经的母穴曲泉，因为只有肝经络过阴器，大敦一下，一痛就收回去了。然后曲泉一下，肠子就开始蠕动循环了，开疝气的药里面再加润肠的药，把大便通出来，譬如开当归四逆汤里面加升麻，因为脱肠所以加升麻，加过药后，临床上，如果小便不利、摄护腺肥大，就是真武汤加减，如果手脚冰冷用当归四逆汤作加减。  \n\n白朮是利三焦油网。  \n\n     葳蕤专门治咽喉不利、喉咙痛、喉咙肿胀，麦门冬和麻子仁是相表里，麦门冬和天门冬 都是润肺的，因为肝的血逆流上来的时候，血带来了很大的热度，就是炎，上焦会热起来了，舌苔会黄，这时候会吐血，靠天门冬润肺，葳蕤止血把热往下降，通利喉咙，因为下焦太寒了，所以有干姜等，药物是寒热并用，因为上焦太热了，所以用石膏。 ","videoMemo":"","fangList":["麻黄升麻汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '382、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{麻黄升麻汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LnYcMAT2wog', 4, '{"title":"373、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也","description":"<p>373、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001132,"note":"      肚子里面有痛的话，代表里寒很盛了，寒湿很盛，转气下趋少腹者就是肠鸣，就是水渗到肠子里面去了、此欲自利也。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '373、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5LjMPlqLUuZ', 4, '{"title":"33","description":"<p>374、伤寒，本自寒下，医复吐、下之，寒格，更逆吐、下，若食入口即吐者，$f{干姜黄连黄芩人参汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001133,"note":"      本自寒下，本来有寒在下焦，医复吐、下之，寒格，更逆吐、下，若食入口即吐者，这也是上热下寒的症状、但是并没有下利。  \n\n     张仲景讲食入口即吐有一个是大黄甘草汤证，大黄二甘草一，这是胃家的热实，热而且有实在中间，东西吃下去马上吐掉，这里的饮食入口即吐也是，但是这个入口即吐是虚热，病人本身已经被吐、下，肠胃津液已经伤到了，本来就是寒的、所以用干姜来去寒，又有虚热，热就是炎，本身有发炎，有病毒，但是没有食物堵在里面，所以用黄芩、黄连来消炎，这人被吐被下肠胃津液一定伤到了，所以加人参，这种病人的症状有的时候舌苔白的有的时候黄的，不一定，下利臭，有的时候下利臭舌苔白的，代表寒盛里面又有热，这是虚热不是实热。这个方常用来治疗现在说的胰脏癌，另外一个胰脏癌常用的处方是旋覆代赭汤加干姜吴茱萸，这是用在病人严重呕吐、呕酸很多的时候；胰脏癌的病人如果还有往来寒热，就会用到小柴胡汤。  \n\n     手术开刀，手术前不能吃东西，手朮后又没吃东西，要等到放屁出来才能吃，由于肠子都黏在一起，这时候最好用的就是独参汤，单独一味人参。\n","videoMemo":"","fangList":["干姜黄连黄芩人参汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '374、伤寒，本自寒下，医复吐、下之，寒格，更逆吐、下，若食入口即吐者，$f{干姜黄连黄芩人参汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kHDQJbYSVlx', 4, '{"title":"375、下利，有微热而渴，脉弱者，令自愈","description":"<p>375、下利，有微热而渴，脉弱者，令自愈。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001134,"note":"      这就是很好的现象，病人下利，脉弱，脉弱代表肠子里面的病毒跟着利通通跑掉了，如果脉跳的数，代表病毒还在里面，这病毒包括霍乱、疟疾的病毒，微热，就是肠胃的功能慢慢恢复了，脉弱者，令自愈，脉弱的自己会好，所以霍乱、疟疾都要参考厥阴证，在难民营里，常常霍乱、疟疾一来就死很多人，因为难民营里的人饮食不好，固表力没了，病毒一下子就到了厥阴证，就会死一大堆人。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '375、下利，有微热而渴，脉弱者，令自愈。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kLwGUi1tf9r', 4, '{"title":"376、下利，脉缓，有微热，汗出，令自愈；设复紧，为末解","description":"<p>376、下利，脉缓，有微热，汗出，令自愈；设复紧，为末解。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001135,"note":"     如果脉又紧回来了，就是免疫系统和病毒相抗，代表余毒没有去掉，为未解。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '376、下利，脉缓，有微热，汗出，令自愈；设复紧，为末解。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C5Kvn1K0Vse', 4, '{"title":"36","description":"<p>377、下利，手足厥冷，无脉者，灸之不温，若脉不还，反微喘者，死。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001136,"note":"      人一直在下利，人就虚弱掉了，手足厥冷，这手脚冰冷都是冷到手肘边了，无脉者，脉没有了，就是心脏衰竭了，灸之不温，灸关元都不会温，若脉不还，反微喘者。死，灸了半天还没有回来，就是寒极了。脏腑的功能都衰竭掉了，所以西医讲的肾衰竭、心脏衰竭，都是寒。为什么微喘?因为寒到上面来了，气进不去，但是可以出来，吸少呼多","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '377、下利，手足厥冷，无脉者，灸之不温，若脉不还，反微喘者，死。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gYyl0NzcIPk', 4, '{"title":"37","description":"<p>379、下利，寸脉反浮数，尺中自涩者，必圊脓血。（校正注：“圊”同“清”）</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001137,"note":"       涩代表血虚了，寸脉反浮数是上热，尺中自涩者，代表血往下走，必圊脓血，病人在拉血的时候，还有精神就没关系，他可能是痔疮出血、如果下血人很虚弱，就是体能不够了，血离经了，因为肠子破了，霍乱、疟疾的时候，肠壁被腐蚀掉了，破洞了，真正的血跑出来了，遇到这种情形的时候，病人一定极度的虚弱。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '379、下利，寸脉反浮数，尺中自涩者，必圊脓血。（校正注：“圊”同“清”）', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZKGe7S0xun0', 4, '{"title":"380、下利清谷，不可攻表，汗出，必胀满","description":"<p>380、下利清谷，不可攻表，汗出，必胀满。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001138,"note":"      下利清谷，代表肠子里面虚寒了，里寒很盛的时候，绝对不可以攻表，因为攻表是靠里面的阳，肠胃的津液来的，如果误攻了，汗出，必胀满。一攻的时候，里寒会更盛了，腹就是胀满，就是整个肿在里面了，肠胃都没有蠕动，松张了。所以病人有呕吐、下利，里虚的时候，绝对不可以攻表。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '380、下利清谷，不可攻表，汗出，必胀满。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DtJoC5bfKlf', 4, '{"title":"39","description":"<p>381、下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001139,"note":"      沉代表里，弦代表急也代表水，所以下利，脉沉弦者，下重也，下利完，脉要到骨边才摸到，细细的一根，病人拉完还想再拉，但是拉不出来，拉出来也是水，就是里急后重，脉一定是沉弦的，如果病人是脉大，代表里面热还是很盛，肠里面还有发炎的现象，利还不会止，脉微弱数者，为欲自止，虽发热，不死，脉微弱，就是阳气慢慢回头的时候，这是好的现象。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '381、下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6UIvp81otxi', 4, '{"title":"40","description":"<p>382、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，病人必微厥。所以然者，其面戴阳，下虚故也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001140,"note":"      沉代表里，迟代表寒，人里寒了，舌苔白的，因为里太虚的时候，会戴阳，就是两颧的地方红红的，这是因为下利太盛，或里寒太盛的时候，阳没有根了，阳气浮起来了，就会看到脸上红红的，主因都是下焦太虚寒。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '382、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，病人必微厥。所以然者，其面戴阳，下虚故也。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SdvkhHM0TZL', 4, '{"title":"383、下利，脉数而渴者，令自愈","description":"<p>383、下利，脉数而渴者，令自愈。设不差，必圊脓血，以有热故也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001141,"note":"      下利虚寒的人，脉数而渴，脉变的数而且口渴，渴就是自己想要喝水，代表寒已经化热了，厥阴证都是寒没有热的。从阴证进入阳证的时候，病人会口渴，阴寒很盛的人都不会口渴，所以病人没事口渴喝水的，不会死，都是阳证，所以喝水就好了，\n     如果设不差，必圊脓血，以有热，喝水没有好，会大便便脓血，因为热太多了，热太过的时候，血会从肠子走，病毒会往肠子里面跑。 ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '383、下利，脉数而渴者，令自愈。设不差，必圊脓血，以有热故也。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('77qHaYkpa4z', 4, '{"title":"42","description":"<p>384、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001142,"note":"       拉肚子拉到脉都没有了，就是心脏衰竭了，手脚冰冷，就是脾脏的功能都没有了，晬时，就是一周时，差不多二十四小时，脉还，手足温者生，胃气回头了生，脉不还者死，这就是辨症，协助断生死用的，遇到这种情形的时候，大剂的四逆汤就下去了，不可以等他死。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '384、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AdTxnKKCXjF', 4, '{"title":"385、伤寒，下利日十余行，脉反实者，死","description":"<p>385、伤寒，下利日十余行，脉反实者，死。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001143,"note":"     伤寒就若是进入厥阴证了，下利的话脉应是微弱，结果脉反实，病人很虚弱，摸到的脉 很实，这就是真脏脉，一般来说癌症的病人有这种脉，摸到的脉跳的很强很硬，就是东西堵到了，过不去了，都是死，所以体内有长肿瘤，脉都跳的很速。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '385、伤寒，下利日十余行，脉反实者，死。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('30chHE2RTVQ', 4, '{"title":"44","description":"<p>386、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001144,"note":"    本来是里寒才会下利清谷，汗出而厥者，里寒外热表示有虚热，通脉四逆汤主之，通脉就是通行上下。  ","videoMemo":"","fangList":["通脉四逆汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '386、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bFbJaZiBxbM', 4, '{"title":"387、热利下重者，$f{白头翁汤治}之","description":"<p>387、热利下重者，$f{白头翁汤治}之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001145,"note":"        痢疾、急性的肠炎，白头翁汤是很常用的方子，热利大便出来很臭，白头翁汤是非常好用的方子，几乎是一剂知二剂已，第一碗喝了就不利了，第二碗喝了就胃口大开，精神好起来了，寒利用通脉四逆汤、热利就用白头翁汤。  \n\n热利的主证：  \n\n    一：手脚不寒  \n\n    二：便臭  \n\n    三：脉数，数代表热代表发炎了 像痢疾的症状就是白头翁汤证，像霍乱、伤寒是下利清谷为主证。  ","videoMemo":"","fangList":["白头翁汤治"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '387、热利下重者，$f{白头翁汤治}之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g6nCbuyNry7', 4, '{"title":"46","description":"<p>388、下利，腹胀满，身体疼痛者，先温其里，乃攻其表，温里宜$f{四逆汤}，攻表宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001146,"note":"       照理说腹胀满，如果是承气汤证，应该不会下利还会便秘的，下利很多，肚子又胀满，就知道里面寒湿很盛，遇到这种里面寒湿很盛的，一定先去里寒去湿，再去解表。","videoMemo":"","fangList":["四逆汤","桂枝汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '388、下利，腹胀满，身体疼痛者，先温其里，乃攻其表，温里宜$f{四逆汤}，攻表宜$f{桂枝汤}。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pN5jGCNJBgA', 4, '{"title":"389、下利，欲饮水者，以有热故也，$f{白头翁汤}主之","description":"<p>389、下利，欲饮水者，以有热故也，$f{白头翁汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001147,"note":"   拉肚子，口又渴，这是热利，寒利不会口渴的，因为津液都跑光了，所以用白头翁汤。  ","videoMemo":"","fangList":["白头翁汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '389、下利，欲饮水者，以有热故也，$f{白头翁汤}主之。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7uNRrShVScf', 4, '{"title":"390、下利，谵语者，有燥矢也，宜$f{大承气汤}","description":"<p>390、下利，谵语者，有燥矢也，宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001148,"note":"        如果大便不通有燥屎的话，应该是小承气汤，现在已经严重到谵语了，就应该是大承气汤，即使下利也是用大承气汤攻，因为大便堵在肠子里面，有间隙产生，看起来是下利，实际上是大便干在里面，只要确定有燥屎在里面，就须用大承气汤、所以有时候会用大承气汤去止利，因为有谵语的症状，谵语的产生，就是大便的浊气跑到脑里面去了。","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '2024-12-02T09:34:23.000Z', '390、下利，谵语者，有燥矢也，宜$f{大承气汤}。', '2024-12-02T09:34:23.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9LlI4d7xhmP', 4, '{"title":"49","description":"<p>391、下利后，更烦，按之心下濡者，为虚烦也，宜$f{栀子豉汤}。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001149,"note":"      如果是心下鞕，代表胀满，是调胃承气汤证，这是实烦，如果是虚烦，就是栀子豉汤，这表示病已经接近好了，常在重病将近痊愈的时候服用。","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '391、下利后，更烦，按之心下濡者，为虚烦也，宜$f{栀子豉汤}。', '2024-12-03T00:33:33.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PVBFktM520v', 4, '{"title":"392、呕家，有痈脓者，不可治呕，脓尽自愈","description":"<p>392、呕家，有痈脓者，不可治呕，脓尽自愈。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001150,"note":"      呕吐的人，有时候吐出来的是脓，从胃里面吐出来像胃痈，或从肺里面吐出来像肺痈、肺里面有脓，所以呕家不可以治呕，要让他先吐，如果病人是干呕、呕酸、呕苦水，这就不是呕家，可以用止呕的药。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '392、呕家，有痈脓者，不可治呕，脓尽自愈。', '2024-12-03T00:33:33.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lxwi6jtqRgJ', 4, '{"title":"51","description":"<p>393、呕而脉弱，小便复利，身有微热，见厥者，难治，$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001151,"note":"       照理说呕吐的病人胃里面虚了，亦即胃里面的津液不够了，所以脉弱，小便复利，小便很多，下焦也是虚寒的，所以中焦、下焦都是虚寒的，身为微热，里面寒湿很盛，体能往外散了，这都是阴太盛，阳不足了，所以四逆汤主之。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '393、呕而脉弱，小便复利，身有微热，见厥者，难治，$f{四逆汤}主之。', '2024-12-03T00:33:33.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DtWDv5L7JAT', 4, '{"title":"394、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之","description":"<p>394、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001152,"note":"       如果呕酸、呕苦，都是从胃里面来的，干呕就代表胃里面没有东西，为什么呕?因为肝脏肿太大了，肝横逆过来了，所以呕出来的黏液，是肝里面的东西，吴茱萸汤主之，吴茱萸汤是专门治呕的方，实际上吴茱萸汤是入肝脏的，西医的胃下垂就是吴茱萸汤证，这种人大部分都是酒客，酒喝多了，肝受不了了，中医看是肝寒，西医看是胃下垂，所以西医对胃下垂从来是治不好的。  ","videoMemo":"","fangList":["吴茱萸汤"],"bieMing":""}}', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '394、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之。', '2024-12-03T00:33:33.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GY65xbCAGJ6', 4, '{"title":"395、呕而发热者，$f{小柴胡汤}主之","description":"<p>395、呕而发热者，$f{小柴胡汤}主之。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001153,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '395、呕而发热者，$f{小柴胡汤}主之。', '2024-12-03T00:33:33.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7VqWF2RdvLn', 4, '{"title":"54","description":"<p>396、伤寒，大吐大下之，极虚，以其人外气怫郁，发其汗，复极汗出者，复与之水，因得哕；所以然者，胃中寒冷故也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001154,"note":"        大吐大下后，津液一定伤到了，极虚的时候病人已经很虚了，看病人体外还是有体温，医师误诊，没有注意到里虚，再开了发汗的药，汗一出来，病人更虚，更虚的状况下，肠胃整个的虚寒掉了，这时候喝了水下去就得哕，用茯苓四逆汤，张仲景没出方子，但是讲的就是茯苓四逆汤，因为胃里面有停水，哕就是打嗝，打嗝就是胃气已绝，没有胃气了，胃没有蠕动了，这时候一喝水下去，水停在胃里面，就会造成打嗝，中医讲的胃气绝就是胃寒，西医讲的就是胃没有吸收功能了，这时候水一下去就会打嗝，因为水是寒的冷的，所以是茯苓四逆汤证，四逆汤加茯苓，把水排掉。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '396、伤寒，大吐大下之，极虚，以其人外气怫郁，发其汗，复极汗出者，复与之水，因得哕；所以然者，胃中寒冷故也。', '2024-12-03T00:33:33.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sI2FsIcy6HT', 4, '{"title":"397、伤寒，哕而腹满，视其前后，知何部不利，利之即愈","description":"<p>397、伤寒，哕而腹满，视其前后，知何部不利，利之即愈。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904001155,"note":"      如果在打嗝，肚子又胀满，视其前后，知何部不利，利之即愈，看看大小便哪一个不通，通哪一个，前部不利开五苓散，后部不利开承气汤，基本上这种状况都是能治的，如果不能治的话，就是人已经虚掉了，这时候攻下都没有用，如果病人是寒湿很盛的话，又哕，还是用茯苓四逆汤去救逆，如果肚子里面有实堵到，就茯苓四逆汤里面加去实的药，大黄去实，大黄没有所谓的寒热，如果是小便不出来，可以加猪苓、泽泻，但是一定以四逆汤为主证。  \n\n以上讲的是厥阴证。  \n\n        原伤寒论之末篇辨霍乱病脉证并治法，辨阴阳易瘥后劳复脉证，辨痉湿暍脉证，这三脉证有经方家并列入伤寒之末篇，但又是《金匮》之始篇，实介于伤寒与金匮之间的连接篇，个人认为伤寒到最末厥阴篇即可止，这最后三篇可置于《金匮》之首篇，以衔接《伤寒》与《金匮》本源于一书伤寒杂病论。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '2024-12-03T00:33:33.000Z', '397、伤寒，哕而腹满，视其前后，知何部不利，利之即愈。', '2024-12-03T00:33:33.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', 'sf2su7oyycM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dURjIiBSJ50', 1, '{"title":"桂枝汤","description":"<p> $u{ 桂枝}$w{三两、去皮}   $u{芍药}$w{三两}   $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}  </p>\n<p></p>\n<p>       $s{右五味}，㕮咀三味，以水七升，微火煮取三升，去滓，适寒温，服一升。服已须臾，啜热稀粥一升余，以助药力。温覆令一时许，遍身絷絷微似有汗者益佳。不可令如水流漓，病必不除。若一服汗出，病差，停后服，不必尽剂。若不汗，更服依前法。又不汗，服后小促其间，半日许，令三服尽。若病重者，一日一夜服，周时观之，服一剂尽，病证犹在者，更作服。若汗不出，乃服至二三剂。禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物。  </p>\n<p></p>\n<p>      用七碗水，用大火煮，古时候生柴火煮汤药，柴火的“微火”等于现在瓦斯炉的大火，煮成三碗渣拿掉，等温了再喝，一次服一碗。服了以后，等一下再喝热稀饭一碗，来帮忙药力。然后，被子盖起来，躺一时，差不多二个小时，全身微发汗。最好，把感冒病毒从汗排出来了，但是没有伤到体内的津液，这样最刚好。如果药开太重，一下子大汗出就不好了。汗出了以后，不能当风，也不能烤火，都不好。如果第一碗下去，好了就好了，不要把剩下的药喝掉。如果不流汗，再喝一碗，还不流汗，服后小促其间，就是缩短服的时间，就是三到四小时。  </p>\n<p></p>\n<p>        半日许，令三服尽，十二小时喝三碗，若病重者，一日一夜服，周时观之，就是每四小时喝一次，日夜都服，服一剂尽，病证犹在者，更作服，再去煮，若汗不出，乃服至二三剂。喝桂枝汤中间禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物，臭恶就是腌制的东西，臭豆腐等等，为什么要禁？桂枝汤是恢复胃阳、脾脏功能的药，就汤剂来看，桂枝壮心让动脉的血流出去，白芍让血流回心脏，所以心脏的力量加强，火生土，土就是脾脏，所以桂枝汤喝下去，脾就充满了血，脾在胃的下方，脾一充血，胃下面很多血管，一充血，胃就开始收缩，就肚子饿，想吃东西，所以桂枝汤是让胃口恢复的药。生冷、粘滑、肉面、五辛、酒酪、臭 恶等物，这些东西都是容易腐败的。吃了肉类，会有浮热产生，对病情恢复有影响；如果吃了生冷的东西，会抵消阳药发汗的效果，因此都要避免。喝完桂枝汤，为什么喝热稀饭？在中医的观念认为稀饭、白饭是最好的营养，肠胃最能吸收的是稀饭。平时吃蕃薯稀饭可以保护脾胃，蕃薯与稀饭各一半，对养生很好。  </p>\n<p></p>\n<p>      桂枝汤最明显的表证就是有汗，代表皮肤毛孔没病的，是滤过性病毒在肌肉里面，因此桂枝汤是解肌的。如果滤过性病毒在皮肤毛孔，皮肤毛孔就封闭起来了，就会没有汗。  </p>\n<p></p>\n<p>       红枣：朱雀，就是保护胃的，红枣的加减很重要，红枣是甘饴的东西，很甜，平常肚子（中焦）湿热比较盛的人。如果加了红枣会增甘加腻、遇到这种情形，把红枣拿掉。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":1,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":null,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":"","showName":"桂枝","extraProcess":"去皮"}]}}', '2024-11-19T09:30:58.000Z', '2024-11-19T09:30:58.000Z', '2024-11-19T09:30:58.000Z', '$u{ 桂枝}$w{三两、去皮} $u{芍药}$w{三两} $u{甘草}$w{二两、炙} $u{生姜}$w{三两、切} $u{大枣}$w{十二枚、擘} $s{右五味}，㕮咀三味，以水七升，微火煮取三升，去滓，适寒温，服一升。服已须臾，啜热稀粥一升余，以助药力。温覆令一时许，遍身絷絷微似有汗者益佳。不可令如水流漓，病必不除。若一服汗出，病差，停后服，不必尽剂。若不汗，更服依前法。又不汗，服后小促其间，半日许，令三服尽。若病重者，一日一夜服，周时观之，服一剂尽，病证犹在者，更作服。若汗不出，乃服至二三剂。禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物。 用七碗水，用大火煮，古时候生柴火煮汤药，柴火的“微火”等于现在瓦斯炉的大火，煮成三碗渣拿掉，等温了再喝，一次服一碗。服了以后，等一下再喝热稀饭一碗，来帮忙药力。然后，被子盖起来，躺一时，差不多二个小时，全身微发汗。最好，把感冒病毒从汗排出来了，但是没有伤到体内的津液，这样最刚好。如果药开太重，一下子大汗出就不好了。汗出了以后，不能当风，也不能烤火，都不好。如果第一碗下去，好了就好了，不要把剩下的药喝掉。如果不流汗，再喝一碗，还不流汗，服后小促其间，就是缩短服的时间，就是三到四小时。 半日许，令三服尽，十二小时喝三碗，若病重者，一日一夜服，周时观之，就是每四小时喝一次，日夜都服，服一剂尽，病证犹在者，更作服，再去煮，若汗不出，乃服至二三剂。喝桂枝汤中间禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物，臭恶就是腌制的东西，臭豆腐等等，为什么要禁？桂枝汤是恢复胃阳、脾脏功能的药，就汤剂来看，桂枝壮心让动脉的血流出去，白芍让血流回心脏，所以心脏的力量加强，火生土，土就是脾脏，所以桂枝汤喝下去，脾就充满了血，脾在胃的下方，脾一充血，胃下面很多血管，一充血，胃就开始收缩，就肚子饿，想吃东西，所以桂枝汤是让胃口恢复的药。生冷、粘滑、肉面、五辛、酒酪、臭 恶等物，这些东西都是容易腐败的。吃了肉类，会有浮热产生，对病情恢复有影响；如果吃了生冷的东西，会抵消阳药发汗的效果，因此都要避免。喝完桂枝汤，为什么喝热稀饭？在中医的观念认为稀饭、白饭是最好的营养，肠胃最能吸收的是稀饭。平时吃蕃薯稀饭可以保护脾胃，蕃薯与稀饭各一半，对养生很好。 桂枝汤最明显的表证就是有汗，代表皮肤毛孔没病的，是滤过性病毒在肌肉里面，因此桂枝汤是解肌的。如果滤过性病毒在皮肤毛孔，皮肤毛孔就封闭起来了，就会没有汗。 红枣：朱雀，就是保护胃的，红枣的加减很重要，红枣是甘饴的东西，很甜，平常肚子（中焦）湿热比较盛的人。如果加了红枣会增甘加腻、遇到这种情形，把红枣拿掉。', '2024-11-19T09:30:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('37H3m4Vnd7N', 1, '{"title":"桂枝加葛根汤","description":"<p> $u{ 桂枝}$w{三两、去皮}    $u{ 芍药}$w{三两}    $u{ 生姜}$w{三两、切}   $u{ 甘草}$w{二两、炙}    $u{ 大枣}$w{十二枚、擘}    $u{ 葛根}$w{四两}  右六味，以水七升，内诸药，煮取三升，去滓，温服一升，不须啜粥，余如桂枝汤将息，及禁忌法。  </p>\n<p></p>\n<p>         不需要喝稀饭，因为葛根发阳的力量很强，所以就不用稀饭来加强发汗。桂枝和芍药等量，葛根要加重，所以如果桂枝三钱，葛根就要用四钱，如果桂枝五钱，葛根用六钱。如果葛根用的比较轻，葛根就无法发到背部，就被桂枝芍药带到四肢上去了。如果要葛根到脸部就要重用，譬如面部中风、口歪眼邪、在对侧合谷下针先麻醉，再地仓透颊车，矫正后，针人中、承浆定位，再开桂枝加葛根汤给病人服用，如果桂枝三，葛根重用到六，吃下去，第二天全部回正，麻感会全去掉的。  </p>\n<p></p>\n<p>        临床上，小孩子的感冒，常常都见到桂枝加葛根汤证，因为小孩子很皮、很好动，流汗很多的情况下吹到风，因为津液流失很多，所以也需要用到葛根。还有一种情形，体力劳动工作的人，冬天劳动的时候，汗出的同时伤于寒，到了来年夏至以前，发为温病，可能用到桂枝加葛根汤或是葛根汤。  </p>\n<p></p>\n<p>       临床上，看到扁桃腺发炎，针灸用少商、商阳放血，扁桃腺点刺放血；配合列缺、照海。汤药可以用桂枝加葛根汤，加上连翘、银花、浮萍、蝉蜕，这里的葛根用到四钱就好。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":2,"yaoCount":6,"drinkNum":3,"yaoList":["葛根","大枣","生姜","甘草","芍药","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":"MzvPguhXJ5G","amount":"四两","weight":null,"suffix":"","showName":"葛根","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":null,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":"","showName":"桂枝","extraProcess":"去皮"}]}}', '2024-11-20T06:21:30.000Z', '2024-11-20T06:21:30.000Z', '2024-11-20T06:21:30.000Z', '$u{ 桂枝}$w{三两、去皮} $u{ 芍药}$w{三两} $u{ 生姜}$w{三两、切} $u{ 甘草}$w{二两、炙} $u{ 大枣}$w{十二枚、擘} $u{ 葛根}$w{四两} 右六味，以水七升，内诸药，煮取三升，去滓，温服一升，不须啜粥，余如桂枝汤将息，及禁忌法。 不需要喝稀饭，因为葛根发阳的力量很强，所以就不用稀饭来加强发汗。桂枝和芍药等量，葛根要加重，所以如果桂枝三钱，葛根就要用四钱，如果桂枝五钱，葛根用六钱。如果葛根用的比较轻，葛根就无法发到背部，就被桂枝芍药带到四肢上去了。如果要葛根到脸部就要重用，譬如面部中风、口歪眼邪、在对侧合谷下针先麻醉，再地仓透颊车，矫正后，针人中、承浆定位，再开桂枝加葛根汤给病人服用，如果桂枝三，葛根重用到六，吃下去，第二天全部回正，麻感会全去掉的。 临床上，小孩子的感冒，常常都见到桂枝加葛根汤证，因为小孩子很皮、很好动，流汗很多的情况下吹到风，因为津液流失很多，所以也需要用到葛根。还有一种情形，体力劳动工作的人，冬天劳动的时候，汗出的同时伤于寒，到了来年夏至以前，发为温病，可能用到桂枝加葛根汤或是葛根汤。 临床上，看到扁桃腺发炎，针灸用少商、商阳放血，扁桃腺点刺放血；配合列缺、照海。汤药可以用桂枝加葛根汤，加上连翘、银花、浮萍、蝉蜕，这里的葛根用到四钱就好。', '2024-11-20T06:21:30.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4CiNQHeBmn3', 1, '{"title":"桂枝加厚朴杏仁汤","description":"<p>$u{桂枝}$w{三两、去皮}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{芍药}$w{三两}    $u{大枣}$w{十二枚、擘}    $u{厚朴}$w{二两、炙去皮}    $u{杏仁}$w{五十枚。去皮尖}</p>\n<p>\t上七味。以水七升。微火煮取三升。去滓。温服一升。覆取微似汗。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":3,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","甘草","芍药","生姜","大枣","厚朴","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"Hs7PKqMqKRj","amount":"五十枚","weight":null,"suffix":"","showName":"杏仁","extraProcess":"去皮尖"},{"yaoId":"8714SID7nWu","amount":"二两","weight":null,"suffix":"","showName":"厚朴","extraProcess":"炙去皮"},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":null,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":"","showName":"桂枝","extraProcess":"去皮"}]}}', '2024-11-20T07:32:08.000Z', '2024-11-20T07:32:08.000Z', '2024-11-20T07:32:08.000Z', '$u{桂枝}$w{三两、去皮} $u{甘草}$w{二两、炙} $u{生姜}$w{三两、切} $u{芍药}$w{三两} $u{大枣}$w{十二枚、擘} $u{厚朴}$w{二两、炙去皮} $u{杏仁}$w{五十枚。去皮尖} 上七味。以水七升。微火煮取三升。去滓。温服一升。覆取微似汗。', '2024-11-20T07:32:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HZLLAaYU52g', 1, '{"title":"桂枝加附子汤","description":"<p>$u{桂枝}$w{三两}    $u{芍药}$w{三两}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两}    $u{大枣}$w{十二枚、擘 }    $u{附子}$w{一枚，炮}  ，去皮破八片 右六味，以水六升，微火煮取三升，去滓，适寒温，服一升。若一服汗止，停后服。  </p>\n<p>【本云桂枝汤。今加附子。将息如前法。】</p>\n<p>  适寒温。等温了再服，若一服汗止，停后服，吃完一服后，汗停了就不要再喝了。  </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":4,"yaoCount":6,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣","附子"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"一枚","weight":null,"suffix":"","showName":"附子","extraProcess":"炮去皮破八片"},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":null,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":"","showName":"桂枝","extraProcess":"去皮"}]}}', '2024-11-20T07:38:36.000Z', '2024-11-20T07:38:36.000Z', '2024-11-20T07:38:36.000Z', '$u{桂枝}$w{三两} $u{芍药}$w{三两} $u{甘草}$w{二两、炙} $u{生姜}$w{三两} $u{大枣}$w{十二枚、擘 } $u{附子}$w{一枚，炮} ，去皮破八片 右六味，以水六升，微火煮取三升，去滓，适寒温，服一升。若一服汗止，停后服。 【本云桂枝汤。今加附子。将息如前法。】 适寒温。等温了再服，若一服汗止，停后服，吃完一服后，汗停了就不要再喝了。', '2024-11-20T07:38:36.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
